window.QBANK = window.QBANK || {};
window.QBANK["smp-ips"] = {
  level: "SMP", subject: "IPS", duration: 900,
  questions: [
    { q: "Indonesia terletak pada 6°LU–11°LS. Dampak letak astronomis tersebut bagi Indonesia adalah....", options: ["beriklim tropis dengan dua musim", "terletak di antara dua benua", "menjadi jalur perdagangan dunia", "memiliki tiga daerah waktu"], answer: 0, solution: "1. Letak astronomis adalah posisi suatu wilayah berdasarkan garis lintang dan garis bujur. 2. Indonesia berada pada 6°LU–11°LS sehingga dilalui garis khatulistiwa. 3. Daerah di sekitar khatulistiwa beriklim tropis dengan dua musim, yaitu musim kemarau dan musim penghujan." },
    { q: "Secara geografis Indonesia terletak di antara Benua Asia dan Benua Australia serta di antara Samudra Hindia dan Samudra Pasifik. Keuntungan letak geografis tersebut adalah....", options: ["Indonesia berada pada posisi silang jalur perdagangan dunia", "Indonesia beriklim tropis sepanjang tahun", "Indonesia memiliki keanekaragaman hayati yang tinggi", "Indonesia rawan gempa bumi dan gunung api"], answer: 0, solution: "1. Letak geografis adalah posisi berdasarkan kenyataan di permukaan bumi, bukan garis lintang/bujur. 2. Posisi di antara dua benua dan dua samudra menempatkan Indonesia pada posisi silang (cross position). 3. Akibatnya Indonesia menjadi jalur lalu lintas pelayaran dan perdagangan dunia." },
    { q: "Ibu kota negara Vietnam adalah....", options: ["Hanoi", "Ho Chi Minh", "Bangkok", "Phnom Penh"], answer: 0, solution: "1. Vietnam adalah negara anggota ASEAN yang terletak di Semenanjung Indochina. 2. Ibu kota Vietnam adalah Hanoi yang terletak di bagian utara. 3. Ho Chi Minh memang kota terbesar di Vietnam, tetapi bukan ibu kota — inilah miskonsepsi yang paling umum." },
    { q: "Ibu kota negara Myanmar adalah....", options: ["Yangon", "Naypyidaw", "Vientiane", "Bangkok"], answer: 1, solution: "1. Myanmar adalah negara ASEAN yang letaknya paling barat. 2. Ibu kota Myanmar saat ini adalah Naypyidaw sejak tahun 2005. 3. Yangon (dulu disebut Rangoon) adalah bekas ibu kota, sehingga banyak yang masih menyangkanya sebagai ibu kota." },
    { q: "Negara anggota ASEAN yang letaknya paling barat adalah....", options: ["Thailand", "Myanmar", "Indonesia", "Malaysia"], answer: 1, solution: "1. Kesepuluh negara ASEAN membentang dari barat hingga timur. 2. Myanmar terletak paling barat dan berbatasan dengan Bangladesh serta India. 3. Thailand terletak di sebelah timur Myanmar, jadi bukan yang paling barat." },
    { q: "Negara yang berbatasan darat langsung dengan Indonesia di Pulau Kalimantan adalah....", options: ["Brunei Darussalam", "Malaysia", "Papua Nugini", "Timor Leste"], answer: 1, solution: "1. Pulau Kalimantan terbagi atas wilayah Indonesia, Malaysia, dan Brunei. 2. Malaysia (negara bagian Sabah dan Sarawak) berbatasan darat langsung dengan Kalimantan bagian Indonesia. 3. Brunei hanya berbatasan dengan Malaysia; Papua Nugini berbatasan di Pulau Papua; Timor Leste berbatasan di Pulau Timor." },
    { q: "ASEAN didirikan pada 8 Agustus 1967 melalui Deklarasi Bangkok oleh lima negara, yaitu....", options: ["Indonesia, Malaysia, Filipina, Singapura, Thailand", "Indonesia, Malaysia, Brunei, Vietnam, Laos", "Indonesia, Thailand, Myanmar, Kamboja, Laos", "Malaysia, Singapura, Vietnam, Filipina, Brunei"], answer: 0, solution: "1. Deklarasi Bangkok ditandatangani pada 8 Agustus 1967 di Bangkok, Thailand. 2. Lima negara pendirinya adalah Indonesia, Malaysia, Filipina, Singapura, dan Thailand. 3. Brunei, Vietnam, Laos, Myanmar, dan Kamboja bergabung belakangan, bukan pendiri." },
    { q: "Sungai terpanjang di dunia adalah....", options: ["Sungai Amazon", "Sungai Nil", "Sungai Mississippi", "Sungai Yangtze"], answer: 1, solution: "1. Sungai Nil di Afrika memiliki panjang sekitar 6.650 km. 2. Sungai Amazon di Amerika Selatan panjangnya sekitar 6.400 km — terpanjang kedua, tetapi debit airnya terbesar di dunia. 3. Jadi sungai terpanjang di dunia adalah Sungai Nil, bukan Amazon." },
    { q: "Samudra terluas di dunia adalah....", options: ["Samudra Pasifik", "Samudra Atlantik", "Samudra Hindia", "Samudra Arktik"], answer: 0, solution: "1. Samudra Pasifik luasnya sekitar 165 juta km², menutupi sepertiga permukaan bumi. 2. Urutan samudra dari terluas: Pasifik, Atlantik, Hindia, kemudian Arktik yang terkecil. 3. Indonesia diapit Samudra Pasifik di timur dan Samudra Hindia di barat." },
    { q: "Daerah penghasil batu bara terbesar di Indonesia adalah....", options: ["Kalimantan Timur", "Jawa Barat", "Sulawesi Selatan", "Papua"], answer: 0, solution: "1. Batu bara terbentuk dari fosil tumbuhan yang tertimbun jutaan tahun lalu. 2. Cadangan batu bara terbesar Indonesia terdapat di Kalimantan Timur dan Sumatra Selatan. 3. Kalimantan Timur tercatat sebagai penghasil batu bara terbesar di Indonesia." },
    { q: "Kepulauan Bangka Belitung terkenal sebagai daerah penghasil tambang....", options: ["nikel", "timah", "emas", "tembaga"], answer: 1, solution: "1. Bangka Belitung adalah kepulauan di sebelah timur Pulau Sumatra. 2. Daerah ini kaya akan timah dan sudah ditambang sejak zaman kolonial Belanda. 3. Nikel banyak terdapat di Sulawesi, sedangkan emas dan tembaga banyak di Papua." },
    { q: "Daerah penghasil nikel terbesar di Indonesia, yang menjadi bahan baku baterai kendaraan listrik, adalah....", options: ["Kalimantan Timur", "Sulawesi Tengah (Morowali)", "Sumatra Selatan", "Jawa Timur"], answer: 1, solution: "1. Nikel adalah logam penting sebagai bahan baku baterai kendaraan listrik. 2. Cadangan nikel terbesar Indonesia terdapat di Sulawesi, terutama di Morowali, Sulawesi Tengah. 3. Berkat cadangan ini Indonesia menjadi salah satu produsen nikel terbesar di dunia." },
    { q: "Tambang emas dan tembaga Grasberg yang dikelola PT Freeport terletak di provinsi....", options: ["Papua", "Kalimantan Timur", "Sulawesi Tenggara", "Nusa Tenggara Barat"], answer: 0, solution: "1. Grasberg di Timika adalah salah satu tambang emas dan tembaga terbesar di dunia. 2. Tambang ini terletak di Pegunungan Jayawijaya, Papua. 3. Hasil tambangnya menjadi salah satu sumber devisa penting bagi Indonesia." },
    { q: "Kota Duri di Provinsi Riau terkenal sebagai daerah penghasil....", options: ["minyak bumi", "batu bara", "timah", "bauksit"], answer: 0, solution: "1. Riau adalah salah satu provinsi penghasil minyak bumi terbesar di Indonesia. 2. Ladang minyak Duri dan Minas di Riau telah dieksploitasi sejak lama. 3. Batu bara banyak di Kalimantan dan timah di Bangka Belitung, bukan di Duri." },
    { q: "Cadangan gas alam terbesar di Indonesia terdapat di....", options: ["Blok Natuna, Kepulauan Riau", "Blok Cepu, Jawa Timur", "lepas pantai Balikpapan", "Teluk Bintuni, Papua Barat"], answer: 0, solution: "1. Gas alam adalah sumber energi fosil yang penting bagi Indonesia. 2. Cadangan gas alam terbesar Indonesia terdapat di Blok Natuna, Kepulauan Riau. 3. Blok Cepu terkenal sebagai penghasil minyak bumi, bukan gas alam terbesar." },
    { q: "Pembangkit Listrik Tenaga Panas Bumi (PLTP) Kamojang yang memanfaatkan energi geothermal terletak di....", options: ["Jawa Barat", "Sumatra Utara", "Sulawesi Utara", "Kalimantan Selatan"], answer: 0, solution: "1. Indonesia dilalui jalur cincin api (ring of fire) sehingga kaya energi panas bumi. 2. PLTP Kamojang adalah pembangkit panas bumi pertama dan tertua di Indonesia. 3. Kamojang terletak di Jawa Barat, di kawasan Gunung Guntur." },
    { q: "Berikut ini yang termasuk sumber daya alam yang dapat diperbarui adalah....", options: ["minyak bumi", "batu bara", "hutan", "gas alam"], answer: 2, solution: "1. Sumber daya alam yang dapat diperbarui adalah yang dapat pulih kembali dalam waktu relatif singkat. 2. Hutan dapat ditanam kembali melalui reboisasi sehingga termasuk dapat diperbarui. 3. Minyak bumi, batu bara, dan gas alam membutuhkan jutaan tahun untuk terbentuk sehingga tidak dapat diperbarui." },
    { q: "Berikut ini yang termasuk sumber daya alam nonhayati adalah....", options: ["kayu jati", "ikan tuna", "batu bara", "rotan"], answer: 2, solution: "1. Sumber daya alam hayati berasal dari makhluk hidup, sedangkan nonhayati bukan dari makhluk hidup. 2. Kayu jati, ikan tuna, dan rotan berasal dari makhluk hidup sehingga termasuk hayati. 3. Batu bara digolongkan sebagai barang tambang (nonhayati) meskipun berasal dari fosil tumbuhan." },
    { q: "Kegiatan ekonomi yang menyalurkan barang dari produsen kepada konsumen disebut....", options: ["produksi", "distribusi", "konsumsi", "investasi"], answer: 1, solution: "1. Ada tiga kegiatan ekonomi pokok: produksi, distribusi, dan konsumsi. 2. Produksi adalah kegiatan menghasilkan barang, konsumsi adalah kegiatan memakai barang. 3. Distribusi adalah kegiatan menyalurkan barang dari produsen ke konsumen, misalnya oleh pedagang dan jasa angkutan." },
    { q: "Contoh kegiatan distribusi dalam kehidupan sehari-hari adalah....", options: ["petani memanen padi di sawah", "sopir mengangkut sayur ke pasar", "siswa membeli buku di toko", "nelayan menangkap ikan di laut"], answer: 1, solution: "1. Produksi adalah kegiatan menghasilkan barang: petani memanen padi dan nelayan menangkap ikan. 2. Konsumsi adalah kegiatan memakai atau membeli barang: siswa membeli buku. 3. Distribusi adalah kegiatan menyalurkan barang, contohnya sopir mengangkut sayur ke pasar." },
    { q: "Rumah tangga ekonomi yang berperan sebagai pemilik faktor-faktor produksi (tanah, tenaga kerja, modal) adalah....", options: ["rumah tangga produsen", "rumah tangga konsumen (keluarga)", "pemerintah", "masyarakat luar negeri"], answer: 1, solution: "1. Faktor-faktor produksi (tanah, tenaga kerja, modal, kewirausahaan) dimiliki oleh rumah tangga konsumen atau keluarga. 2. Rumah tangga konsumen menyewakan atau menjual faktor produksi tersebut kepada perusahaan. 3. Rumah tangga produsen justru pengguna faktor produksi — inilah yang sering tertukar." },
    { q: "Pasar yang diselenggarakan setahun sekali, misalnya Pekan Raya Jakarta, digolongkan sebagai pasar....", options: ["harian", "mingguan", "bulanan", "tahunan"], answer: 3, solution: "1. Pasar dapat digolongkan menurut waktu penyelenggaraannya. 2. Ada pasar harian, mingguan, bulanan, dan tahunan. 3. Pekan Raya Jakarta (Jakarta Fair) diadakan setahun sekali sehingga termasuk pasar tahunan." },
    { q: "Badan usaha yang beranggotakan orang-seorang dengan asas kekeluargaan dan bertujuan mensejahterakan anggota disebut....", options: ["BUMN", "koperasi", "firma", "perseroan terbatas"], answer: 1, solution: "1. UUD 1945 Pasal 33 ayat (1) menyatakan perekonomian disusun sebagai usaha bersama berdasar atas asas kekeluargaan. 2. Badan usaha yang sesuai dengan amanat konstitusi tersebut adalah koperasi. 3. Karena itu koperasi dijuluki soko guru perekonomian Indonesia." },
    { q: "Kawasan perdagangan bebas ASEAN yang mulai diberlakukan tahun 1992 adalah....", options: ["MEA", "AFTA", "WTO", "APEC"], answer: 1, solution: "1. AFTA (ASEAN Free Trade Area) disepakati tahun 1992 untuk menghapus hambatan tarif antarnegara ASEAN. 2. MEA (Masyarakat Ekonomi ASEAN) adalah pasar tunggal yang berlaku tahun 2015 dan cakupannya lebih luas dari AFTA. 3. WTO dan APEC adalah kerja sama perdagangan tingkat dunia, bukan khusus ASEAN." },
    { q: "Kebutuhan yang harus dipenuhi manusia agar dapat bertahan hidup, seperti makanan dan pakaian, disebut kebutuhan....", options: ["primer", "sekunder", "tersier", "mewah"], answer: 0, solution: "1. Kebutuhan menurut tingkat kepentingannya dibagi menjadi primer, sekunder, dan tersier. 2. Kebutuhan primer adalah kebutuhan pokok untuk bertahan hidup: sandang, pangan, dan papan. 3. Kebutuhan tersier (mewah) justru yang paling tidak mendesak — jangan tertukar dengan primer." },
    { q: "Dorongan dalam diri manusia untuk melakukan kegiatan ekonomi demi memenuhi kebutuhan disebut....", options: ["prinsip ekonomi", "motif ekonomi", "tindakan ekonomi", "hukum permintaan"], answer: 1, solution: "1. Motif ekonomi adalah alasan atau dorongan seseorang melakukan kegiatan ekonomi. 2. Contohnya motif memenuhi kebutuhan hidup dan motif mencari keuntungan. 3. Prinsip ekonomi berbeda: yaitu bertindak dengan pengorbanan sekecil-kecilnya untuk hasil sebesar-besarnya." },
    { q: "VOC (Vereenigde Oostindische Compagnie) didirikan oleh Belanda pada tahun....", options: ["1511", "1596", "1602", "1799"], answer: 2, solution: "1. Tahun 1596 adalah kedatangan Cornelis de Houtman di Banten — itu awal kedatangan Belanda, bukan berdirinya VOC. 2. VOC didirikan pada tahun 1602 sebagai kongsi dagang Belanda di Asia. 3. Tahun 1799 adalah tahun VOC dibubarkan karena bangkrut dan korupsi para pegawainya." },
    { q: "Tujuan utama VOC mendirikan kongsi dagang di Indonesia adalah....", options: ["menyebarkan agama Kristen", "memonopoli perdagangan rempah-rempah", "membangun Jalan Raya Anyer–Panarukan", "menghapus sistem tanam paksa"], answer: 1, solution: "1. Rempah-rempah Indonesia sangat mahal harganya di Eropa pada abad ke-17. 2. VOC dibentuk untuk memonopoli perdagangan rempah dan menyingkirkan pesaing seperti Portugis dan Inggris. 3. Untuk itu VOC diberi hak istimewa (hak octrooi), antara lain mencetak uang dan memiliki tentara." },
    { q: "Gubernur Jenderal Daendels yang memerintah tahun 1808–1811 terkenal karena membangun....", options: ["sistem tanam paksa", "Jalan Raya Anyer–Panarukan", "politik etis", "benteng pertahanan di Maluku"], answer: 1, solution: "1. Daendels ditugasi mempertahankan Pulau Jawa dari serangan Inggris. 2. Ia membangun Jalan Raya Pos dari Anyer (Banten) sampai Panarukan (Jawa Timur) sepanjang kurang lebih 1.100 km. 3. Pembangunan jalan tersebut memakan banyak korban jiwa akibat kerja paksa (rodi)." },
    { q: "Sistem tanam paksa (Cultuurstelsel) yang menyengsarakan rakyat Indonesia diberlakukan pada tahun 1830 oleh....", options: ["Daendels", "Raffles", "Van den Bosch", "Van Deventer"], answer: 2, solution: "1. Cultuurstelsel mewajibkan petani menanam tanaman ekspor seperti kopi, tebu, dan nila. 2. Sistem ini dicetuskan oleh Gubernur Jenderal Van den Bosch pada tahun 1830. 3. Daendels terkenal dengan jalan raya, Raffles dengan masa pemerintahan Inggris, dan Van Deventer dengan Politik Etis." },
    { q: "Politik Etis yang dicetuskan Van Deventer pada tahun 1901 berisi tiga program yang disebut Trias van Deventer, yaitu....", options: ["irigasi, edukasi, emigrasi", "monopoli, tanam paksa, kerja rodi", "eksplorasi, eksploitasi, ekspansi", "nasionalisasi, industrialisasi, modernisasi"], answer: 0, solution: "1. Politik Etis adalah politik balas budi Belanda atas keuntungan besar dari tanam paksa. 2. Isinya disebut Trias van Deventer: irigasi (pengairan), edukasi (pendidikan), dan emigrasi atau transmigrasi (perpindahan penduduk). 3. Program edukasi melahirkan kaum terpelajar yang menjadi pelopor pergerakan nasional Indonesia." },
    { q: "Organisasi Budi Utomo yang menjadi tonggak Hari Kebangkitan Nasional didirikan pada....", options: ["20 Mei 1908", "28 Oktober 1928", "1 Juni 1945", "17 Agustus 1945"], answer: 0, solution: "1. Budi Utomo didirikan pada 20 Mei 1908 oleh para pelajar STOVIL atas gagasan dr. Wahidin Sudirohusodo. 2. Tanggal berdirinya diperingati sebagai Hari Kebangkitan Nasional. 3. Tanggal 28 Oktober 1928 adalah Sumpah Pemuda dan 17 Agustus 1945 adalah Proklamasi Kemerdekaan." },
    { q: "Ikrar Sumpah Pemuda yang diucapkan pada 28 Oktober 1928 berisi tekad....", options: ["Indonesia segera merdeka dari penjajahan", "bertumpah darah satu, berbangsa satu, berbahasa satu: Indonesia", "menolak segala bentuk penjajahan asing", "mendirikan negara federasi Indonesia"], answer: 1, solution: "1. Kongres Pemuda II pada 28 Oktober 1928 menghasilkan ikrar Sumpah Pemuda. 2. Isinya: bertumpah darah yang satu tanah air Indonesia, berbangsa yang satu bangsa Indonesia, dan menjunjung bahasa persatuan bahasa Indonesia. 3. Ikrar ini menjadi fondasi persatuan dan kesatuan bangsa Indonesia." },
    { q: "Naskah Proklamasi Kemerdekaan Indonesia pada 17 Agustus 1945 dibacakan oleh....", options: ["Ir. Soekarno didampingi Drs. Moh. Hatta", "Drs. Moh. Hatta didampingi Ir. Soekarno", "Mr. Soepomo dan Mr. A.A. Maramis", "Jenderal Soedirman dan Bung Tomo"], answer: 0, solution: "1. Teks proklamasi dirumuskan di rumah Laksamana Maeda pada dini hari 17 Agustus 1945. 2. Atas usul Sukarni, naskah dibacakan oleh Ir. Soekarno didampingi Drs. Moh. Hatta. 3. Pembacaan dilakukan di Jalan Pegangsaan Timur No. 56 Jakarta pada pukul 10.00." },
    { q: "Dalam sidang BPUPKI tanggal 1 Juni 1945, Ir. Soekarno mengusulkan....", options: ["Piagam Jakarta", "Pancasila sebagai dasar negara", "teks Proklamasi Kemerdekaan", "Undang-Undang Dasar 1945"], answer: 1, solution: "1. Sidang pertama BPUPKI (29 Mei–1 Juni 1945) membahas dasar negara Indonesia merdeka. 2. Pada 1 Juni 1945 Soekarno berpidato mengusulkan lima dasar negara yang dinamainya Pancasila. 3. Tanggal 1 Juni kemudian diperingati sebagai Hari Lahir Pancasila." },
    { q: "Peristiwa Rengasdengklok yang mendesak Soekarno-Hatta segera memproklamasikan kemerdekaan terjadi pada....", options: ["14 Agustus 1945", "15 Agustus 1945", "16 Agustus 1945", "17 Agustus 1945"], answer: 2, solution: "1. Jepang menyerah kepada Sekutu pada 14 Agustus 1945 sehingga terjadi kekosongan kekuasaan (vacuum of power). 2. Golongan muda membawa Soekarno-Hatta ke Rengasdengklok pada 16 Agustus 1945 agar proklamasi tidak menunggu keputusan PPKI. 3. Proklamasi akhirnya dibacakan keesokan harinya, 17 Agustus 1945." },
    { q: "Perang Diponegoro, perang terbesar melawan Belanda pada abad ke-19, berlangsung pada tahun....", options: ["1825–1830", "1873–1904", "1945–1949", "1901–1908"], answer: 0, solution: "1. Perang Diponegoro dipimpin oleh Pangeran Diponegoro di Jawa. 2. Perang berlangsung selama lima tahun, yaitu 1825–1830. 3. Perang ini sangat menguras kas Belanda sehingga menjadi salah satu pemicu diberlakukannya tanam paksa tahun 1830." },
    { q: "Hasil Konferensi Meja Bundar (KMB) yang diselenggarakan pada akhir tahun 1949 di Den Haag adalah....", options: ["Indonesia menjadi negara bagian Belanda", "Belanda mengakui kedaulatan Republik Indonesia Serikat", "Belanda segera menyerahkan Irian Barat", "Indonesia membayar ganti rugi perang"], answer: 1, solution: "1. KMB adalah perundingan antara Indonesia dan Belanda setelah Agresi Militer Belanda II. 2. Hasilnya: Belanda mengakui kedaulatan Republik Indonesia Serikat (RIS). 3. Penyerahan kedaulatan dilaksanakan pada 27 Desember 1949." },
    { q: "Di Indonesia, sensus penduduk dilaksanakan setiap....", options: ["1 tahun sekali", "5 tahun sekali", "10 tahun sekali", "25 tahun sekali"], answer: 2, solution: "1. Sensus penduduk adalah pencacahan seluruh penduduk yang dilaksanakan oleh BPS. 2. Di Indonesia sensus penduduk dilaksanakan setiap 10 tahun sekali. 3. Pemilu yang dilaksanakan 5 tahun sekali sering tertukar dengan sensus — keduanya berbeda." },
    { q: "Rumus untuk menghitung kepadatan penduduk adalah....", options: ["$D = \\\\frac{\\\\text{Jumlah Penduduk}}{\\\\text{Luas Wilayah}}$", "$D = \\\\frac{\\\\text{Luas Wilayah}}{\\\\text{Jumlah Penduduk}}$", "$D = \\\\text{Jumlah Penduduk} \\\\times \\\\text{Luas Wilayah}$", "$D = \\\\text{Jumlah Penduduk} + \\\\text{Luas Wilayah}$"], answer: 0, solution: "1. Kepadatan penduduk menunjukkan rata-rata jumlah penduduk pada setiap satuan luas wilayah. 2. Rumusnya: kepadatan penduduk = jumlah penduduk dibagi luas wilayah. 3. Satuannya adalah jiwa per km²; rumus yang dibalik (luas dibagi penduduk) adalah kesalahan yang umum terjadi." },
    { q: "Pulau di Indonesia yang memiliki kepadatan penduduk tertinggi adalah....", options: ["Sumatra", "Jawa", "Kalimantan", "Sulawesi"], answer: 1, solution: "1. Pulau Jawa luasnya hanya sekitar 7% dari wilayah Indonesia. 2. Namun lebih dari separuh penduduk Indonesia tinggal di Pulau Jawa. 3. Akibatnya Jawa menjadi pulau terpadat di Indonesia, bahkan salah satu yang terpadat di dunia." },
    { q: "Bentuk piramida penduduk Indonesia yang dicirikan oleh angka kelahiran tinggi dan penduduk usia muda yang banyak adalah piramida....", options: ["ekspansif", "konstruktif", "stasioner", "kerucut"], answer: 0, solution: "1. Piramida ekspansif berbentuk limas dengan alas yang lebar: penduduk usia muda jumlahnya sangat banyak. 2. Ciri ini menandakan angka kelahiran dan kematian yang tinggi, umum di negara berkembang. 3. Indonesia termasuk piramida ekspansif; piramida konstruktif justru untuk negara maju dengan angka kelahiran rendah." },
    { q: "Perpindahan penduduk dari desa ke kota untuk mencari pekerjaan disebut....", options: ["transmigrasi", "urbanisasi", "emigrasi", "imigrasi"], answer: 1, solution: "1. Urbanisasi adalah perpindahan penduduk dari desa ke kota. 2. Transmigrasi adalah perpindahan penduduk antar pulau dalam satu negara. 3. Emigrasi adalah pindah ke luar negeri, sedangkan imigrasi adalah masuk dari luar negeri." },
    { q: "Warga negara Indonesia yang pindah dan menetap di luar negeri disebut....", options: ["imigran", "emigran", "transmigran", "urban"], answer: 1, solution: "1. Emigrasi adalah perpindahan penduduk ke luar negeri untuk menetap; pelakunya disebut emigran. 2. Imigran adalah orang asing yang masuk dan menetap di Indonesia. 3. Cara mengingatnya: emigrasi = exit (keluar), imigrasi = in (masuk)." },
    { q: "Salah satu dampak negatif ledakan penduduk di Indonesia adalah....", options: ["meningkatnya pendapatan per kapita", "meningkatnya angka pengangguran", "berkurangnya kemacetan lalu lintas", "bertambahnya lahan pertanian"], answer: 1, solution: "1. Ledakan penduduk berarti jumlah penduduk tumbuh lebih cepat daripada ketersediaan lapangan kerja. 2. Akibatnya angka pengangguran dan kemiskinan meningkat. 3. Pendapatan per kapita justru menurun bila pertumbuhan ekonomi kalah cepat dari pertumbuhan penduduk." },
    { q: "Upaya pemerintah Indonesia untuk menekan laju pertumbuhan penduduk adalah melalui program....", options: ["transmigrasi", "Keluarga Berencana (KB)", "urbanisasi", "industrialisasi"], answer: 1, solution: "1. Program Keluarga Berencana (KB) mengajak setiap keluarga memiliki dua anak cukup. 2. Program ini menekan angka kelahiran sehingga laju pertumbuhan penduduk menurun. 3. Transmigrasi bertujuan pemerataan persebaran penduduk, bukan menekan angka kelahiran." },
    { q: "Faktor utama yang mendorong terjadinya globalisasi adalah....", options: ["letak geografis yang strategis", "perkembangan ilmu pengetahuan dan teknologi", "jumlah penduduk yang besar", "iklim tropis yang mendukung"], answer: 1, solution: "1. Globalisasi adalah proses mendunianya berbagai aspek kehidupan manusia. 2. Pendorong utamanya adalah kemajuan ilmu pengetahuan dan teknologi, terutama di bidang transportasi dan komunikasi (internet dan telepon). 3. Tanpa teknologi komunikasi modern, interaksi antarnegara tidak akan secepat sekarang." },
    { q: "Berikut ini yang merupakan dampak positif globalisasi di bidang ekonomi adalah....", options: ["meluasnya pasar produk Indonesia ke luar negeri", "masuknya budaya asing yang merusak moral", "meningkatnya sikap konsumerisme", "lunturnya semangat gotong royong"], answer: 0, solution: "1. Globalisasi membuka hambatan perdagangan antarnegara. 2. Dampak positifnya di bidang ekonomi: produk Indonesia mudah dipasarkan ke luar negeri dan investasi asing masuk ke Indonesia. 3. Tiga opsi lainnya adalah dampak negatif globalisasi di bidang budaya dan sosial." },
    { q: "Dampak negatif globalisasi di bidang budaya bagi Indonesia adalah....", options: ["meningkatnya kunjungan wisatawan", "mudahnya akses informasi", "lunturnya nilai-nilai budaya lokal", "berkembangnya kerja sama pendidikan"], answer: 2, solution: "1. Arus budaya asing masuk sangat deras melalui internet dan media sosial. 2. Bila tidak disaring, budaya lokal terdesak dan nilai-nilai luhur bangsa menjadi luntur (westernisasi). 3. Tiga opsi lainnya justru merupakan dampak positif globalisasi." },
    { q: "Masyarakat Ekonomi ASEAN (MEA) yang menciptakan pasar tunggal di kawasan Asia Tenggara mulai diberlakukan pada tahun....", options: ["1967", "1992", "2015", "2020"], answer: 2, solution: "1. MEA adalah bentuk integrasi ekonomi ASEAN berupa arus bebas barang, jasa, investasi, dan tenaga kerja terampil. 2. MEA resmi diberlakukan pada 31 Desember 2015. 3. Tahun 1967 adalah berdirinya ASEAN dan 1992 adalah kesepakatan AFTA — keduanya sering tertukar dengan MEA." },
    { q: "Minyak bumi, batu bara, dan gas alam digolongkan sebagai sumber daya alam yang tidak dapat diperbarui karena....", options: ["berasal dari sisa fosil makhluk hidup", "terbentuk dalam waktu jutaan tahun sehingga akan habis jika terus dipakai", "berwarna gelap dan beracun", "harganya mahal di pasaran"], answer: 1, solution: "1. Minyak bumi, batu bara, dan gas alam terbentuk dari sisa organisme yang terpendam jutaan tahun. 2. Proses pembentukannya jauh lebih lama daripada kecepatan manusia memakainya, sehingga cadangannya akan habis. 3. Jangan terkecoh: yang menentukan bukan asal fosilnya, melainkan waktu pembentukannya yang sangat lama." },
    { q: "Energi panas bumi (geothermal) termasuk sumber daya alam yang dapat diperbarui karena....", options: ["diambil dari perut bumi yang tidak terlihat", "panas dari dalam bumi terus dihasilkan dan tidak akan habis dalam waktu manusia", "hanya ada di daerah gunung berapi", "tidak menghasilkan listrik"], answer: 1, solution: "1. Panas bumi berasal dari panas inti bumi yang terus-menerus ada. 2. Selama bumi masih panas, uap panas buminya bisa dipakai berulang-ulang tanpa habis. 3. Miskonsepsi umum: karena 'ditambang dari perut bumi' lalu dikira sama seperti batu bara, padahal panasnya terus diperbarui secara alami." },
    { q: "Padi, kayu jati, dan ikan tuna digolongkan sebagai sumber daya alam hayati karena....", options: ["berasal dari dalam tanah", "merupakan makhluk hidup atau berasal dari makhluk hidup", "bisa dimakan manusia", "jumlahnya tidak terbatas"], answer: 1, solution: "1. SDA hayati (biotik) artinya bersumber dari makhluk hidup. 2. Padi dan jati adalah tumbuhan, tuna adalah hewan, jadi ketiganya makhluk hidup. 3. Jangan terkecoh: batu bara memang berasal dari tumbuhan purba, tetapi sudah menjadi benda mati (mineral) sehingga digolongkan nonhayati." },
    { q: "Pasangan jenis sumber daya alam dan contohnya yang tepat adalah....", options: ["dapat diperbarui – batu bara", "hayati – padi", "tidak dapat diperbarui – air sungai", "nonhayati – kayu jati"], answer: 1, solution: "1. Padi adalah tumbuhan (makhluk hidup), jadi termasuk SDA hayati. 2. Batu bara tidak dapat diperbarui, air sungai dapat diperbarui, dan kayu jati itu hayati, jadi tiga pasangan lain salah. 3. Miskonsepsi umum: mengira kayu itu nonhayati karena 'benda mati' setelah ditebang, padahal asalnya makhluk hidup." },
    { q: "Tanah yang berasal dari abu letusan gunung berapi dan dikenal paling subur di Indonesia adalah tanah....", options: ["andosol (vulkanis)", "gambut", "latosol", "regosol"], answer: 0, solution: "1. Abu vulkanik kaya unsur hara seperti fosfor dan kalium. 2. Tanah hasil pelapukannya disebut tanah andosol atau tanah vulkanis, tersebar di sekitar gunung berapi Jawa dan Sumatera. 3. Jangan terkecoh tanah gambut yang tebal dan hitam, warnanya gelap bukan berarti subur, justru bersifat asam." },
    { q: "Di dataran rendah pantai utara Jawa banyak terdapat tanah hasil endapan lumpur sungai yang subur. Tanah tersebut dinamakan tanah....", options: ["andosol", "grumosol", "gambut", "aluvial"], answer: 3, solution: "1. Lumpur yang diendapkan aliran sungai di dataran rendah membentuk tanah aluvial. 2. Endapan ini membawa unsur hara dari hulu sehingga tanahnya subur, cocok untuk sawah. 3. Jangan terkecoh tanah gambut yang juga ada di dataran rendah, gambut berasal dari timbunan sisa tumbuhan di rawa, bukan endapan sungai." },
    { q: "Tanah gambut banyak terdapat di rawa Kalimantan dan Sumatera. Kelemahan utama tanah gambut untuk pertanian adalah....", options: ["terlalu subur sehingga gulma tumbuh liar", "bersifat asam, miskin hara, dan mudah terbakar saat kemarau", "terlalu keras untuk dicangkul", "tidak bisa menyerap air sama sekali"], answer: 1, solution: "1. Gambut terbentuk dari timbunan sisa tumbuhan yang membusuk di rawa. 2. Akibatnya tanahnya asam, miskin unsur hara, dan saat kering sangat mudah terbakar. 3. Miskonsepsi umum: karena warnanya hitam pekat dikira sangat subur seperti tanah vulkanik, padahal kesuburannya rendah." },
    { q: "Hutan berfungsi menyimpan air hujan lalu melepaskannya perlahan ke sungai pada musim kemarau. Fungsi hutan tersebut dinamakan fungsi....", options: ["hidrologis", "orologis", "klimatologis", "edafis"], answer: 0, solution: "1. Kata 'hidrologis' berasal dari 'hidro' yang berarti air. 2. Fungsi ini mengatur tata air: menyerap hujan saat basah, melepasnya saat kering. 3. Jangan tertukar dengan fungsi orologis (mencegah erosi) atau klimatologis (mengatur iklim). Ingat: hidro = air." },
    { q: "Fungsi hutan dalam mencegah erosi dan tanah longsor di daerah miring disebut fungsi....", options: ["hidrologis", "klimatologis", "orologis", "edafis"], answer: 2, solution: "1. Akar pepohonan mencengkeram tanah sehingga tidak mudah tergerus air hujan. 2. Fungsi menahan tanah dari erosi dan longsor ini disebut fungsi orologis. 3. Jangan tertukar dengan fungsi hidrologis yang mengatur air; cara ingatnya: orologis menjaga 'tanah', hidrologis menjaga 'air'." },
    { q: "Indonesia dijuluki paru-paru dunia karena hutan hujan tropisnya....", options: ["menjadi tempat wisata yang terkenal", "menghasilkan oksigen dan menyerap karbon dioksida dalam jumlah besar", "menampung seluruh air hujan Indonesia", "menghasilkan kayu terbanyak di dunia"], answer: 1, solution: "1. Daun-daun hutan melakukan fotosintesis: menyerap CO2 dan melepaskan oksigen. 2. Karena hutan Indonesia sangat luas, perannya bagi udara dunia amat besar, seperti paru-paru bagi tubuh. 3. Miskonsepsi umum: mengira julukan ini karena hutannya menghasilkan kayu, padahal maksudnya peran ekologisnya bagi udara." },
    { q: "Ciri khas hutan hujan tropis di Indonesia adalah....", options: ["pepohonan menggugurkan daun pada musim kemarau", "tumbuh di daerah kering dengan curah hujan rendah", "pepohonan selalu hijau dengan tajuk berlapis-lapis", "hanya ditumbuhi satu jenis pohon"], answer: 2, solution: "1. Hujan turun sepanjang tahun sehingga pohon tidak pernah kekurangan air. 2. Akibatnya daun selalu hijau dan tajuk pohon tersusun berlapis (strata) dari semak hingga pohon raksasa. 3. Jangan tertukar dengan hutan musim yang menggugurkan daun saat kemarau, itu ciri daerah bercurah hujan rendah." },
    { q: "Penebangan hutan secara liar dan besar-besaran dapat mengakibatkan....", options: ["banjir dan tanah longsor", "udara menjadi makin sejuk", "tanah menjadi makin subur", "air sumur menjadi makin jernih"], answer: 0, solution: "1. Tanpa pepohonan, air hujan tidak terserap dan langsung mengalir deras ke sungai. 2. Tanah yang tidak dicengkeram akar pun mudah longsor, sehingga terjadi banjir dan longsor. 3. Miskonsepsi umum: mengira membuka hutan membuat lahan 'bersih dan bermanfaat', padahal fungsi pelindung hutannya hilang." },
    { q: "Pulau Buton di Sulawesi Tenggara terkenal sebagai daerah penghasil tambang....", options: ["timah", "nikel", "aspal", "intan"], answer: 2, solution: "1. Perut bumi Pulau Buton menyimpan deposit aspal alam yang besar. 2. Aspal Buton dipakai untuk campuran pengaspalan jalan di Indonesia. 3. Jangan tertukar: timah dari Bangka Belitung, nikel dari Sulawesi (Morowali), intan dari Martapura." },
    { q: "Kawah Ijen di Banyuwangi, Jawa Timur, terkenal sebagai daerah penghasil....", options: ["emas", "belerang", "intan", "marmer"], answer: 1, solution: "1. Kawah Ijen mengeluarkan gas belerang yang mengkristal di sekitar kawah. 2. Belerang ini ditambang secara tradisional oleh para penambang Ijen. 3. Jangan terkecoh: emas terkenal dari Papua (Grasberg), intan dari Martapura, marmer dari Tulungagung." },
    { q: "Kota Martapura di Kalimantan Selatan terkenal sebagai daerah penghasil....", options: ["intan (berlian)", "batu bara", "bauksit", "emas"], answer: 0, solution: "1. Daerah Cempaka di Martapura sudah lama dikenal sebagai penghasil intan. 2. Intan adalah mineral paling keras yang dipakai untuk perhiasan dan mata bor. 3. Jangan tertukar dengan batu bara yang memang banyak di Kalimantan, tetapi Martapura khususnya terkenal karena intannya." },
    { q: "Kabupaten Tulungagung di Jawa Timur terkenal sebagai daerah penghasil....", options: ["batu bara", "timah", "emas", "marmer"], answer: 3, solution: "1. Perbukitan kapur di Tulungagung menghasilkan marmer berkualitas baik. 2. Marmer dipakai untuk lantai, meja, dan ukiran karena motifnya indah. 3. Jangan terkecoh: batu bara dari Kalimantan/Sumatera, timah dari Bangka Belitung, emas dari Papua." },
    { q: "Pulau Bintan di Kepulauan Riau terkenal sebagai daerah penghasil....", options: ["timah", "bauksit", "nikel", "tembaga"], answer: 1, solution: "1. Tanah di Bintan kaya akan bauksit, bijih utama pembuat aluminium. 2. Aluminium dari bauksit dipakai untuk pesawat, panci, dan kabel listrik. 3. Jangan tertukar dengan timah (Bangka Belitung) atau nikel (Sulawesi); ketiganya logam berbeda dari daerah berbeda." },
    { q: "Blok Cepu di perbatasan Jawa Tengah dan Jawa Timur terkenal sebagai daerah penghasil....", options: ["gas alam", "batu bara", "minyak bumi", "emas"], answer: 2, solution: "1. Lapangan minyak Blok Cepu adalah salah satu penghasil minyak bumi terbesar di Jawa. 2. Minyak bumi diolah menjadi bensin, solar, dan minyak tanah. 3. Miskonsepsi umum: mengira minyak dan gas selalu satu paket; di Cepu komoditas utamanya minyak bumi." },
    { q: "Kilang gas alam Arun yang pernah menjadi salah satu yang terbesar di dunia terletak di provinsi....", options: ["Aceh", "Riau", "Kalimantan Timur", "Papua"], answer: 0, solution: "1. Ladang gas Arun berada di Lhokseumawe, Aceh. 2. Gasnya dicairkan (LNG) lalu diekspor ke Jepang dan Korea. 3. Jangan tertukar dengan Natuna (Kepulauan Riau) atau Bontang (Kalimantan Timur) yang juga penghasil gas." },
    { q: "Minyak bumi disebut bahan bakar fosil karena....", options: ["ditemukan bersama fosil dinosaurus", "berwarna hitam seperti fosil", "terbentuk dari sisa-sisa organisme yang terpendam jutaan tahun", "hanya bisa dipakai mesin kuno"], answer: 2, solution: "1. Minyak bumi berasal dari jasad renik laut (plankton) yang tertimbun lumpur jutaan tahun lalu. 2. Panas dan tekanan bumi mengubahnya menjadi minyak, jadi disebut 'fosil' karena asal usulnya. 3. Miskonsepsi umum: mengira dari fosil dinosaurus, padahal sebagian besar dari organisme laut berukuran renik." },
    { q: "Pembangkit Listrik Tenaga Bayu (angin) pertama di Indonesia, PLTB Sidrap, terletak di provinsi....", options: ["Jawa Barat", "Nusa Tenggara Timur", "Sulawesi Selatan", "Bali"], answer: 2, solution: "1. Kincir angin raksasa PLTB Sidrap berdiri di Kabupaten Sidenreng Rappang. 2. Daerah ini dipilih karena anginnya kencang dan stabil sepanjang tahun. 3. Jangan terkecoh: pembangkit panas bumi memang banyak di Jawa Barat (Kamojang), tetapi tenaga angin pertamanya ada di Sulawesi Selatan." },
    { q: "PLTA Cirata dan Saguling yang memanfaatkan aliran Sungai Citarum terletak di provinsi....", options: ["Jawa Barat", "Jawa Tengah", "Jawa Timur", "Banten"], answer: 0, solution: "1. Sungai Citarum mengalir di Jawa Barat dan dibendung untuk PLTA. 2. Waduk Cirata dan Saguling mengubah energi gerak air menjadi listrik. 3. Jangan tertukar dengan PLTA Jatiluhur yang juga di Jawa Barat, tetapi Cirata-Saguling memang satu aliran Citarum." },
    { q: "Indonesia sangat berpotensi mengembangkan energi surya (matahari) karena....", options: ["memiliki banyak gunung berapi", "terletak di daerah tropis dengan penyinaran matahari sepanjang tahun", "dikelilingi lautan yang luas", "memiliki banyak sungai besar"], answer: 1, solution: "1. Indonesia dilalui garis khatulistiwa sehingga matahari bersinar hampir sepanjang tahun. 2. Penyinaran yang merata inilah modal utama panel surya. 3. Miskonsepsi umum: mengira gunung berapi berkaitan dengan surya, padahal gunung berapi berkaitan dengan energi panas bumi." },
    { q: "Alasan utama energi fosil perlu digantikan energi terbarukan adalah....", options: ["energi fosil terlalu murah", "energi fosil mudah diperbarui", "cadangan fosil terbatas dan pembakarannya mencemari udara", "energi fosil tidak bisa menghasilkan listrik"], answer: 2, solution: "1. Minyak, gas, dan batu bara akan habis karena terbentuk jutaan tahun. 2. Pembakarannya juga menghasilkan gas rumah kaca penyebab pemanasan global. 3. Jangan terkecoh: fosil justru tidak murah dalam jangka panjang dan jelas bisa menghasilkan listrik, masalahnya pada ketersediaan dan polusinya." },
    { q: "Sebagai negara kepulauan, Indonesia kaya ikan tuna. Daerah yang terkenal sebagai penghasil ikan tuna adalah....", options: ["perairan timur Indonesia seperti Maluku", "Sungai Musi di Sumatera", "Danau Toba di Sumatera Utara", "Waduk Jatiluhur di Jawa Barat"], answer: 0, solution: "1. Tuna adalah ikan laut lepas yang hidup di samudra. 2. Perairan timur Indonesia seperti Maluku dan sekitar Bitung menjadi jalur dan daerah penangkapan tuna. 3. Miskonsepsi umum: mengira semua ikan berasal dari sungai atau danau, padahal tuna hanya hidup di laut." },
    { q: "Rumput laut banyak dibudidayakan di perairan Nusa Tenggara dan Sulawesi. Manfaat utama rumput laut adalah....", options: ["bahan bakar kendaraan", "bahan bangunan rumah", "bahan baku agar-agar, kosmetik, dan makanan", "bahan peledak"], answer: 2, solution: "1. Rumput laut mengandung karagenan dan agar yang mengental. 2. Bahan ini dipakai untuk agar-agar, es krim, kosmetik, dan obat. 3. Jangan terkecoh: rumput laut bukan untuk bahan bakar atau bangunan, nilainya justru sebagai bahan industri pangan dan kosmetik." },
    { q: "Budidaya mutiara air laut berkembang pesat di Lombok, Nusa Tenggara Barat. Mutiara dihasilkan oleh....", options: ["sejenis ikan karang", "kerang (tiram mutiara)", "rumput laut", "terumbu karang"], answer: 1, solution: "1. Mutiara terbentuk di dalam tubuh kerang tiram mutiara yang melapisi benda asing dengan nacre. 2. Petani mutiara memasukkan inti ke dalam kerang lalu memanennya setelah 2-3 tahun. 3. Miskonsepsi umum: mengira mutiara berasal dari ikan atau karang, padahal hanya kerang tertentu yang menghasilkannya." },
    { q: "Tambak udang dan bandeng banyak terdapat di pantai utara Jawa. Ciri khas tambak yang membedakannya dari kolam biasa adalah....", options: ["terletak di pegunungan yang sejuk", "menggunakan air payau atau asin di tepi pantai", "memakai air tawar dari pegunungan", "khusus untuk ikan hias"], answer: 2, solution: "1. Tambak dibangun di pesisir dan dialiri air laut yang bercampur air tawar (payau). 2. Udang windu dan bandeng memang hidup baik di air payau. 3. Jangan tertukar dengan kolam air tawar untuk lele atau nila; tambak = pesisir = air payau." },
    { q: "Reboisasi adalah kegiatan....", options: ["penanaman kembali hutan yang gundul", "penebangan hutan untuk kayu", "pembukaan hutan menjadi sawah", "pemupukan pohon di hutan"], answer: 0, solution: "1. Kata 'reboisasi' berasal dari 're' (kembali) dan 'bois' (hutan). 2. Artinya menanam kembali pohon di lahan hutan yang gundul agar hutan pulih. 3. Miskonsepsi umum: mengira reboisasi berarti menebang hutan, padahal kebalikannya, yaitu menghijaukan kembali." },
    { q: "Sebelum membangun pabrik di tepi sungai, perusahaan wajib menyusun AMDAL. Tujuan utama AMDAL adalah....", options: ["menghitung keuntungan perusahaan", "mengurus izin usaha", "mengkaji dampak kegiatan terhadap lingkungan", "merekrut karyawan pabrik"], answer: 2, solution: "1. AMDAL adalah Analisis Mengenai Dampak Lingkungan. 2. Dokumen ini memprediksi kerusakan lingkungan yang mungkin terjadi dan cara mencegahnya sebelum proyek berjalan. 3. Jangan terkecoh: AMDAL bukan soal keuntungan atau perizinan semata, fokusnya melindungi lingkungan." },
    { q: "Taman Nasional Komodo di NTT dan Taman Nasional Ujung Kulon di Banten merupakan bentuk....", options: ["eksploitasi sumber daya alam", "konservasi (pelestarian) sumber daya alam", "reboisasi hutan gundul", "kawasan industri"], answer: 1, solution: "1. Taman nasional melindungi hewan, tumbuhan, dan habitatnya dari kerusakan. 2. Komodo dan badak bercula satu dilindungi agar tidak punah, inilah konservasi. 3. Jangan tertukar dengan eksploitasi yang justru mengambil SDA besar-besaran; taman nasional melarang itu." },
    { q: "Prinsip ekonomi dalam pemanfaatan sumber daya alam berarti....", options: ["menggunakan SDA sehemat dan seefisien mungkin untuk hasil sebesar-besarnya", "memakai SDA sebanyak-banyaknya selagi gratis", "menjual seluruh SDA ke luar negeri", "melarang semua pemakaian SDA"], answer: 0, solution: "1. Prinsip ekonomi: pengorbanan sekecil mungkin untuk hasil sebesar mungkin. 2. Dalam SDA artinya tidak boros, tidak merusak, dan hasilnya maksimal untuk kesejahteraan. 3. Miskonsepsi umum: mengira prinsip ekonomi berarti mengeksploitasi habis-habisan demi untung cepat, padahal justru menuntut hemat dan lestari." },
    { q: "Menurut UUD 1945 Pasal 33, bumi, air, dan kekayaan alam yang terkandung di dalamnya dikuasai negara dan dipergunakan untuk....", options: ["keuntungan para pengusaha", "kepentingan pihak asing", "sebesar-besar kemakmuran rakyat", "pendapatan daerah saja"], answer: 2, solution: "1. Pasal 33 ayat 3 UUD 1945 menegaskan penguasaan negara atas kekayaan alam. 2. Tujuannya jelas: sebesar-besar kemakmuran rakyat, bukan segelintir pihak. 3. Jangan terkecoh: SDA boleh dikelola swasta lewat izin, tetapi tujuannya tetap kesejahteraan rakyat." },
    { q: "Petani di daerah pegunungan membuat sawah berundak (terasering). Tujuan utama pembuatan terasering adalah....", options: ["memperluas kawasan hutan", "mempercepat aliran air hujan", "mencegah erosi dan menahan air", "menampung ikan di sawah"], answer: 2, solution: "1. Lereng yang miring membuat air hujan mengalir deras dan menggerus tanah. 2. Undakan-undakan memperlambat aliran air sehingga tanah tidak tererosi dan air tersimpan. 3. Miskonsepsi umum: mengira terasering hanya soal keindahan, padahal fungsi utamanya konservasi tanah dan air." },
    { q: "Agar tanah tidak cepat tandus, petani melakukan rotasi tanaman dan menanam kacang-kacangan. Manfaat utama cara tersebut adalah....", options: ["mengusir semua jenis hama", "mempercepat waktu panen", "mengembalikan unsur hara (nitrogen) ke dalam tanah", "menambah jumlah air tanah"], answer: 2, solution: "1. Tanaman kacang-kacangan (legum) bekerja sama dengan bakteri yang mengikat nitrogen dari udara. 2. Nitrogen ini menyuburkan tanah sehingga tanaman berikutnya tumbuh baik tanpa pupuk berlebih. 3. Jangan terkecoh: rotasi tanaman bukan untuk mengusir hama atau mempercepat panen, melainkan menjaga kesuburan tanah." },
    { q: "Banyak orang mengira air sumur tidak akan pernah habis. Pernyataan yang tepat tentang air tanah adalah....", options: ["air tanah dapat habis jika disedot berlebihan tanpa ada resapan", "air tanah jumlahnya tidak terbatas", "air hujan tidak perlu ditampung karena selalu ada", "air sumur selalu bersih dan aman"], answer: 0, solution: "1. Air tanah berasal dari hujan yang meresap ke dalam tanah. 2. Jika disedot terus tanpa resapan yang cukup, sumur bisa kering, buktinya banyak sumur warga yang kering saat kemarau panjang. 3. Miskonsepsi umum: karena air tampak melimpah saat hujan, dikira cadangannya tak terbatas, padahal perlu dihemat dan diresapkan kembali." },
    { q: "Batu bara sering dikira dapat diperbarui karena berasal dari tumbuhan. Faktanya, batu bara....", options: ["termasuk SDA hayati karena dari tumbuhan", "dapat ditanam kembali seperti padi", "terbentuk dalam hitungan tahun", "tidak dapat diperbarui karena terbentuk selama jutaan tahun"], answer: 3, solution: "1. Batu bara memang berasal dari tumbuhan purba yang terpendam. 2. Namun prosesnya butuh tekanan, panas, dan waktu jutaan tahun, jauh melampaui umur manusia. 3. Miskonsepsi umum: 'dari tumbuhan berarti bisa tumbuh lagi'; yang benar, batu bara sudah menjadi mineral (nonhayati) yang tidak terbarukan." },
    { q: "Timah dari Bangka Belitung banyak dimanfaatkan untuk....", options: ["bahan bakar kendaraan", "pupuk tanaman", "pelapis kaleng makanan dan solder", "bahan obat-obatan"], answer: 2, solution: "1. Timah bersifat tidak beracun dan tahan karat. 2. Karena itu dipakai melapisi kaleng makanan-minuman serta sebagai solder penyambung komponen elektronik. 3. Jangan tertukar dengan nikel (bahan baterai) atau batu bara (bahan bakar); setiap mineral punya kegunaan khasnya." },
    { q: "Komponen peta yang berfungsi menjelaskan arti dari simbol-simbol yang ada pada peta adalah....", options: ["Judul peta","Legenda","Skala","Inset"], answer: 1, solution: "1. Legenda adalah keterangan yang menjelaskan arti setiap simbol pada peta. 2. Tanpa legenda, pembaca tidak tahu arti garis, warna, atau gambar pada peta. 3. Jangan tertukar dengan judul peta: judul menunjukkan isi peta, sedangkan legenda menjelaskan simbolnya." },
    { q: "Pada sebuah peta, jarak 1 cm mewakili jarak sebenarnya 500 m. Penulisan skala angka yang tepat adalah....", options: ["1 : 5.000","1 : 500.000","1 : 50.000","1 : 50"], answer: 2, solution: "1. Ubah 500 m menjadi cm: 500 x 100 = 50.000 cm. 2. Jadi 1 cm pada peta = 50.000 cm sebenarnya, ditulis 1 : 50.000. 3. Kesalahan umum adalah lupa mengubah meter ke cm sehingga memilih 1 : 500." },
    { q: "Garis khayal pada globe yang sejajar dengan garis ekuator disebut garis....", options: ["Lintang","Bujur","Meridian","Ekuator"], answer: 0, solution: "1. Garis lintang adalah garis horizontal yang sejajar dengan ekuator. 2. Garis bujur (meridian) justru tegak lurus, menghubungkan kedua kutub. 3. Ekuator hanyalah salah satu garis lintang, yaitu garis lintang 0 derajat." },
    { q: "Indonesia terbentang dari 95 derajat BT sampai 141 derajat BT. Akibat perbedaan garis bujur yang lebar ini, Indonesia dibagi menjadi....", options: ["2 zona waktu","4 zona waktu","5 zona waktu","3 zona waktu"], answer: 3, solution: "1. Perbedaan bujur yang lebar membuat waktu lokal berbeda-beda di tiap daerah. 2. Agar seragam, Indonesia dibagi menjadi 3 zona: WIB, WITA, dan WIT. 3. Jangan terkecoh: 3 zona berarti selisih WIB-WIT hanya 2 jam, bukan 3 jam." },
    { q: "Pada peta, warna biru umumnya digunakan untuk melambangkan....", options: ["Dataran rendah","Pegunungan","Perairan","Hutan lebat"], answer: 2, solution: "1. Warna biru pada peta melambangkan perairan seperti laut, sungai, dan danau. 2. Warna hijau untuk dataran rendah, cokelat untuk pegunungan. 3. Kesalahan umum adalah mengira biru berarti dataran rendah karena terlihat sejuk." },
    { q: "Proyeksi peta yang paling tepat untuk memetakan wilayah di lintang tengah, misalnya Benua Eropa, adalah proyeksi....", options: ["Azimuthal","Kerucut","Silinder","Datar"], answer: 1, solution: "1. Proyeksi kerucut paling akurat untuk daerah lintang tengah. 2. Proyeksi azimuthal cocok untuk kutub, sedangkan silinder cocok untuk daerah ekuator. 3. Memilih proyeksi yang salah membuat bentuk wilayah terdistorsi." },
    { q: "Ketika di London (GMT) pukul 12.00 siang, waktu di Jakarta (WIB = GMT+7) menunjukkan pukul....", options: ["17.00","05.00","12.00","19.00"], answer: 3, solution: "1. WIB = GMT+7 artinya waktu Jakarta 7 jam lebih cepat dari London. 2. 12.00 + 7 jam = 19.00. 3. Kesalahan umum adalah malah mengurangi 7 jam sehingga menjawab 05.00." },
    { q: "Jarak kota A ke kota B pada peta berskala 1 : 100.000 adalah 6 cm. Jarak sebenarnya kedua kota tersebut adalah....", options: ["60 km","0,6 km","6 km","600 km"], answer: 2, solution: "1. Jarak sebenarnya = 6 x 100.000 cm = 600.000 cm. 2. Ubah ke km: 600.000 : 100.000 = 6 km. 3. Hati-hati dengan jumlah nolnya: 1 km = 100.000 cm, bukan 10.000 cm." },
    { q: "Berikut ini yang termasuk peta tematik (peta khusus) adalah....", options: ["Peta topografi","Peta korografi","Peta persebaran penduduk","Peta dunia"], answer: 2, solution: "1. Peta tematik menggambarkan satu tema khusus, misalnya persebaran penduduk. 2. Peta topografi, korografi, dan peta dunia termasuk peta umum. 3. Jangan terkecoh: peta yang berwarna-warni belum tentu tematik, peta umum pun bisa berwarna." },
    { q: "Garis lintang 0 derajat disebut juga garis....", options: ["Meridian utama","Ekuator","Kutub utara","Garis balik selatan"], answer: 1, solution: "1. Garis lintang 0 derajat adalah garis ekuator atau khatulistiwa. 2. Meridian utama adalah garis bujur 0 derajat, bukan garis lintang 0 derajat. 3. Ini miskonsepsi paling umum: tertukar antara lintang 0 derajat (ekuator) dan bujur 0 derajat (Greenwich)." },
    { q: "Wilayah beriklim tropis terletak pada garis lintang....", options: ["23,5-66,5 derajat LU/LS","66,5-90 derajat LU/LS","0-66,5 derajat LU/LS","0-23,5 derajat LU/LS"], answer: 3, solution: "1. Iklim tropis ada di sekitar ekuator, yaitu 0 sampai 23,5 derajat LU/LS. 2. 23,5-66,5 derajat beriklim sedang, 66,5-90 derajat beriklim kutub. 3. Angka 23,5 derajat adalah batas garis balik, bukan batas daerah tropis seluruhnya." },
    { q: "Simbol titik pada peta biasanya digunakan untuk menggambarkan....", options: ["Kota","Sungai","Jalan raya","Danau"], answer: 0, solution: "1. Simbol titik dipakai untuk objek kecil yang letaknya berupa titik, seperti kota. 2. Sungai dan jalan digambarkan dengan simbol garis, danau dengan simbol area. 3. Ingat polanya: titik untuk kota, garis untuk sungai atau jalan, area untuk danau atau laut." },
    { q: "Inset pada peta berfungsi untuk....", options: ["Menunjukkan arah mata angin","Menjelaskan arti simbol","Memperjelas wilayah yang sempit pada peta utama","Menunjukkan perbandingan jarak"], answer: 2, solution: "1. Inset adalah peta kecil penyisip untuk memperbesar wilayah yang sempit atau tidak jelas pada peta utama. 2. Arah mata angin ditunjukkan oleh orientasi, arti simbol oleh legenda. 3. Jangan tertukar: inset itu gambarnya, bukan keterangannya." },
    { q: "Skala yang dinyatakan dengan kalimat, misalnya 1 cm berbanding 2 km, disebut skala....", options: ["Angka","Garis","Verbal","Nominal"], answer: 2, solution: "1. Skala verbal (incat) dinyatakan dalam bentuk kalimat atau kata-kata. 2. Skala angka ditulis 1 : 200.000, skala garis digambar sebagai garis berskala. 3. Contoh di soal setara dengan skala angka 1 : 200.000 karena 2 km = 200.000 cm." },
    { q: "Kota Makassar berada di zona WITA. Jika di Jakarta (WIB) pukul 08.00, maka di Makassar pukul....", options: ["07.00 WITA","09.00 WITA","10.00 WITA","08.00 WITA"], answer: 1, solution: "1. WITA = GMT+8, WIB = GMT+7, jadi WITA 1 jam lebih cepat dari WIB. 2. 08.00 + 1 jam = 09.00 WITA. 3. Kesalahan umum adalah mengurangi 1 jam (07.00) atau menambah 2 jam (10.00, itu untuk WIT)." },
    { q: "Waktu Indonesia Barat (WIB = GMT+7) berpatokan pada garis bujur....", options: ["105 derajat BT","120 derajat BT","135 derajat BT","90 derajat BT"], answer: 0, solution: "1. Setiap 1 jam = 15 derajat bujur, jadi GMT+7 berpatokan pada 7 x 15 = 105 derajat BT. 2. 120 derajat BT adalah patokan WITA, 135 derajat BT patokan WIT. 3. Jangan tertukar: angka bujur yang lebih besar bukan berarti WIB." },
    { q: "Komponen peta yang menunjukkan arah mata angin disebut....", options: ["Legenda","Inset","Orientasi","Lettering"], answer: 2, solution: "1. Orientasi (tanda orientasi) menunjukkan arah mata angin, biasanya panah ke utara. 2. Legenda menjelaskan simbol, inset memperjelas wilayah sempit. 3. Tanpa orientasi, pembaca peta tidak tahu arah utara peta." },
    { q: "Peta berskala 1 : 25.000 tergolong peta....", options: ["Kadaster","Skala besar","Skala sedang","Skala kecil"], answer: 1, solution: "1. Peta besar berskala 1 : 5.000 sampai 1 : 250.000, jadi 1 : 25.000 termasuk peta besar. 2. Peta kadaster skalanya lebih besar lagi (1 : 100 sampai 1 : 5.000). 3. Miskonsepsi umum: angka skala yang kecil (25.000) justru berarti skala peta BESAR dan detail." },
    { q: "Garis tanggal internasional terletak pada garis bujur....", options: ["0 derajat","90 derajat BT","90 derajat BB","180 derajat"], answer: 3, solution: "1. Garis tanggal internasional berada pada garis bujur 180 derajat, di tengah Samudra Pasifik. 2. Garis bujur 0 derajat adalah meridian utama (Greenwich), patokan waktu dunia. 3. Jangan tertukar antara 0 derajat (patokan jam) dan 180 derajat (patokan tanggal)." },
    { q: "Sebuah pesawat terbang dari Tokyo ke arah timur melintasi Samudra Pasifik menuju Amerika. Saat melintasi garis tanggal internasional, penanggalan pada kalender....", options: ["Mundur satu hari","Maju satu hari","Tetap sama","Mundur satu jam"], answer: 0, solution: "1. Melintasi garis tanggal internasional ke arah timur membuat tanggal berkurang satu hari. 2. Sebaliknya, melintas ke arah barat membuat tanggal bertambah satu hari. 3. Kesalahan umum adalah mengira arah perjalanan tidak berpengaruh pada tanggal." },
    { q: "Langkah pertama yang sebaiknya dilakukan saat membaca peta adalah....", options: ["Menghitung skala peta","Membaca judul peta","Membaca legenda","Mencari arah mata angin"], answer: 1, solution: "1. Bacalah judul peta terlebih dahulu agar tahu isi dan maksud peta. 2. Setelah itu baru perhatikan legenda, skala, dan orientasi. 3. Tanpa tahu judulnya, simbol-simbol pada peta bisa salah ditafsirkan." },
    { q: "Simbol garis pada peta digunakan untuk menggambarkan....", options: ["Kota","Sungai","Danau","Gunung"], answer: 1, solution: "1. Simbol garis dipakai untuk objek memanjang seperti sungai, jalan, dan rel kereta. 2. Kota dan gunung memakai simbol titik, danau memakai simbol area. 3. Ingat: garis = objek memanjang, bukan objek bulat." },
    { q: "Jarak pada peta 4 cm mewakili jarak sebenarnya 2 km. Skala peta tersebut adalah....", options: ["1 : 20.000","1 : 200.000","1 : 50.000","1 : 500.000"], answer: 2, solution: "1. Ubah 2 km menjadi cm: 2 x 100.000 = 200.000 cm. 2. Skala = 200.000 : 4 = 50.000, jadi 1 : 50.000. 3. Kesalahan umum adalah lupa mengubah km ke cm sebelum membagi." },
    { q: "Wilayah Indonesia beriklim tropis. Hal ini terutama disebabkan oleh faktor....", options: ["Letak astronomis","Letak geografis","Letak geologis","Kondisi sosial"], answer: 0, solution: "1. Letak astronomis Indonesia (6 LU-11 LS) dekat ekuator menyebabkan iklim tropis. 2. Letak geografis (di antara dua benua dan dua samudra) berpengaruh pada perdagangan, bukan iklim. 3. Iklim ditentukan oleh garis lintang, bukan oleh posisi di antara benua." },
    { q: "Pada peta fisik, warna cokelat umumnya melambangkan....", options: ["Dataran rendah","Perairan","Pegunungan","Lahan pertanian"], answer: 2, solution: "1. Warna cokelat (makin tua makin tinggi) melambangkan pegunungan dan dataran tinggi. 2. Hijau untuk dataran rendah, biru untuk perairan. 3. Jangan mengira cokelat berarti tanah kering atau gurun." },
    { q: "Globe memiliki keunggulan dibandingkan peta datar karena....", options: ["Bentuknya menyerupai bumi sehingga minim distorsi","Lebih murah dan mudah dibawa","Dapat menunjukkan detail wilayah kecil","Skalanya selalu lebih besar"], answer: 0, solution: "1. Globe berbentuk bola seperti bumi, sehingga bentuk wilayah tidak terdistorsi. 2. Peta datar harus meregangkan permukaan lengkung bumi sehingga pasti ada distorsi. 3. Justru peta datar yang lebih murah, mudah dibawa, dan bisa menampilkan detail wilayah kecil." },
    { q: "Perbedaan waktu antara WIB (GMT+7) dan WIT (GMT+9) adalah....", options: ["1 jam","3 jam","4 jam","2 jam"], answer: 3, solution: "1. Selisihnya = 9 - 7 = 2 jam. 2. Jadi saat di Jakarta pukul 08.00 WIB, di Jayapura pukul 10.00 WIT. 3. Kesalahan umum adalah menjawab 3 jam karena ada 3 zona waktu." },
    { q: "Setiap selisih 1 derajat garis bujur menyebabkan perbedaan waktu lokal sebesar....", options: ["1 menit","15 menit","60 menit","4 menit"], answer: 3, solution: "1. Bumi berputar 360 derajat dalam 24 jam, jadi 15 derajat = 1 jam. 2. Maka 1 derajat = 60 menit : 15 = 4 menit. 3. Jangan tertukar: 15 derajat per jam, bukan 15 menit per derajat." },
    { q: "Simbol yang umumnya digunakan untuk menunjukkan ibu kota negara pada peta adalah....", options: ["Lingkaran kecil","Bintang","Segitiga","Persegi"], answer: 1, solution: "1. Ibu kota negara umumnya disimbolkan dengan bintang. 2. Lingkaran kecil untuk kota biasa, segitiga untuk gunung. 3. Simbol ibu kota dibuat mencolok agar mudah ditemukan pada peta." },
    { q: "Judul peta berfungsi untuk....", options: ["Menjelaskan arti simbol","Menunjukkan isi atau maksud peta","Menunjukkan perbandingan jarak","Menunjukkan arah mata angin"], answer: 1, solution: "1. Judul menunjukkan isi dan maksud peta, misalnya Peta Persebaran Tambang Indonesia. 2. Arti simbol dijelaskan legenda, perbandingan jarak oleh skala. 3. Jangan tertukar dengan legenda: judul itu NAMANYA peta, legenda itu KETERANGAN simbolnya." },
    { q: "Kelemahan proyeksi Mercator yang perlu diketahui adalah....", options: ["Wilayah kutub tampak jauh lebih besar dari aslinya","Arah mata angin tidak akurat","Garis ekuator tampak melengkung","Tidak dapat menunjukkan daerah tropis"], answer: 0, solution: "1. Proyeksi Mercator meregangkan daerah lintang tinggi sehingga kutub tampak sangat besar. 2. Kelebihannya justru arahnya akurat, sehingga cocok untuk navigasi pelayaran. 3. Contohnya Greenland tampak sebesar Afrika, padahal aslinya jauh lebih kecil." },
    { q: "Koordinat geografis suatu tempat terdiri atas....", options: ["Skala dan legenda","Lintang dan ekuator","Garis lintang dan garis bujur","Bujur dan meridian"], answer: 2, solution: "1. Koordinat geografis = garis lintang (posisi utara-selatan) + garis bujur (posisi timur-barat). 2. Ekuator hanyalah salah satu garis lintang, meridian hanyalah nama lain garis bujur. 3. Tanpa keduanya, posisi suatu tempat di permukaan bumi tidak bisa ditentukan." },
    { q: "Peta yang menggambarkan bentuk permukaan bumi seperti gunung, lembah, dan dataran disebut peta....", options: ["Korografi","Kartografi","Geologi","Topografi"], answer: 3, solution: "1. Peta topografi menggambarkan relief permukaan bumi (tinggi-rendahnya wilayah). 2. Kartografi adalah ilmu pembuatan peta, bukan jenis peta. 3. Jangan tertukar dengan korografi (peta umum suatu wilayah) dan peta geologi (jenis batuan)." },
    { q: "Wilayah Indonesia bagian timur, seperti Papua, menggunakan zona waktu....", options: ["WIB","WITA","GMT+10","WIT"], answer: 3, solution: "1. Papua memakai WIT (Waktu Indonesia Timur) = GMT+9. 2. WITA = GMT+8 untuk wilayah tengah, WIB = GMT+7 untuk wilayah barat. 3. Urutannya dari barat: WIB, WITA, WIT - makin ke timur makin cepat." },
    { q: "Garis bujur 0 derajat yang menjadi patokan waktu dunia disebut....", options: ["Ekuator","Meridian utama","Garis balik utara","Garis tanggal"], answer: 1, solution: "1. Garis bujur 0 derajat disebut meridian utama, melewati kota Greenwich, Inggris. 2. Waktu dunia (GMT) dihitung dari garis ini. 3. Jangan tertukar dengan garis tanggal internasional yang berada di 180 derajat." },
    { q: "Fungsi utama skala pada peta adalah....", options: ["Menunjukkan arah mata angin","Menghitung jarak sebenarnya di permukaan bumi","Menjelaskan arti simbol","Memperbesar gambar peta"], answer: 1, solution: "1. Skala adalah perbandingan jarak pada peta dengan jarak sebenarnya, jadi fungsinya menghitung jarak sebenarnya. 2. Arah ditunjukkan orientasi, arti simbol dijelaskan legenda. 3. Tanpa skala, peta hanya gambar tanpa ukuran yang bisa dihitung." },
    { q: "Pada peta, warna hijau umumnya digunakan untuk melambangkan....", options: ["Perairan","Pegunungan","Dataran rendah","Kawasan perkotaan"], answer: 2, solution: "1. Warna hijau melambangkan dataran rendah yang subur. 2. Biru untuk perairan, cokelat untuk pegunungan. 3. Makin tinggi suatu wilayah, warnanya berubah dari hijau ke kuning lalu cokelat." },
    { q: "Jika di Makassar (WITA) sekarang pukul 10.00, maka di Jayapura (WIT) pukul....", options: ["09.00 WIT","12.00 WIT","10.00 WIT","11.00 WIT"], answer: 3, solution: "1. WIT = GMT+9, WITA = GMT+8, jadi WIT 1 jam lebih cepat dari WITA. 2. 10.00 + 1 jam = 11.00 WIT. 3. Kesalahan umum adalah menambah 2 jam (12.00, itu selisih WIT dengan WIB) atau malah mengurangi." },
    { q: "Puncak tertinggi di Indonesia yang puncaknya diselimuti salju abadi adalah....", options: ["Gunung Kerinci di Sumatra", "Puncak Jaya di Papua", "Gunung Semeru di Jawa", "Gunung Rinjani di Lombok"], answer: 1, solution: "1. Puncak Jaya (Carstensz Pyramid) tingginya 4.884 m, puncak tertinggi di Indonesia. 2. Ia berada di Pegunungan Sudirman, Papua, dan saking tingginya puncaknya bersalju abadi. 3. Kerinci memang gunung api tertinggi, tetapi bukan puncak tertinggi — jangan tertukar." },
    { q: "Gunung api tertinggi di Indonesia adalah....", options: ["Gunung Kerinci di Sumatra", "Gunung Semeru di Jawa", "Gunung Merapi di Jawa Tengah", "Gunung Agung di Bali"], answer: 0, solution: "1. Gunung Kerinci tingginya 3.805 m, gunung api tertinggi di Indonesia. 2. Semeru (3.676 m) hanya tertinggi di Pulau Jawa. 3. Merapi terkenal paling aktif, bukan paling tinggi — aktif dan tinggi itu dua hal berbeda." },
    { q: "Gunung tertinggi di Pulau Jawa adalah....", options: ["Gunung Merapi", "Gunung Slamet", "Gunung Semeru", "Gunung Lawu"], answer: 2, solution: "1. Gunung Semeru di Jawa Timur tingginya 3.676 m. 2. Slamet (3.428 m) tertinggi kedua di Jawa, Lawu 3.265 m. 3. Merapi memang terkenal, tetapi tingginya hanya sekitar 2.930 m — terkenal tidak sama dengan tertinggi." },
    { q: "Letusan Gunung Tambora pada tahun 1815 yang sampai menyebabkan 'tahun tanpa musim panas' di Eropa terjadi di pulau....", options: ["Jawa", "Sumatra", "Kalimantan", "Sumbawa"], answer: 3, solution: "1. Gunung Tambora terletak di Pulau Sumbawa, Nusa Tenggara Barat. 2. Letusannya tahun 1815 termasuk yang terbesar dalam sejarah dan abunya menutupi sinar matahari. 3. Banyak yang mengira Tambora di Jawa karena namanya mirip, padahal ia di Sumbawa." },
    { q: "Pulau vulkanik Anak Krakatau yang muncul dari laut pada tahun 1927 terletak di....", options: ["Selat Malaka", "Selat Sunda", "Selat Makassar", "Selat Lombok"], answer: 1, solution: "1. Anak Krakatau tumbuh di lokasi bekas letusan Krakatau 1883, yaitu Selat Sunda. 2. Selat Sunda memisahkan Pulau Jawa dan Pulau Sumatra. 3. Selat Malaka memang terkenal, tetapi Krakatau tidak ada di sana — jangan tertukar karena sama-sama bernama 'selat'." },
    { q: "Pegunungan yang membentang sepanjang Pulau Sumatra dari Aceh sampai Lampung adalah....", options: ["Bukit Barisan", "Pegunungan Jayawijaya", "Pegunungan Kendeng", "Pegunungan Meratus"], answer: 0, solution: "1. Bukit Barisan membentang di sepanjang sisi barat Pulau Sumatra. 2. Di sanalah Gunung Kerinci berada. 3. Jayawijaya ada di Papua dan Meratus di Kalimantan — tiap pulau punya pegunungannya sendiri." },
    { q: "Dataran rendah (ketinggian 0-200 meter di atas permukaan laut) paling cocok dimanfaatkan untuk....", options: ["Pertambangan batu bara", "Perkebunan teh di lereng curam", "Persawahan dan permukiman penduduk", "Pembangkit listrik tenaga bayu"], answer: 2, solution: "1. Dataran rendah itu datar dan subur sehingga cocok untuk sawah, kota, dan industri. 2. Contohnya Pantura Jawa yang penuh sawah dan kota-kota besar. 3. Teh justru cocok di dataran tinggi yang sejuk — kebalikannya." },
    { q: "Lembah Baliem yang menjadi rumah Suku Dani terletak di kawasan pegunungan....", options: ["Bukit Barisan", "Jayawijaya", "Kendeng", "Meratus"], answer: 1, solution: "1. Lembah Baliem berada di Pegunungan Jayawijaya, Papua. 2. Lembah adalah cekungan di antara pegunungan yang biasanya dialiri sungai. 3. Bukit Barisan ada di Sumatra — Baliem jelas di Papua, jangan tertukar." },
    { q: "Pengikisan pantai oleh hantaman gelombang air laut disebut....", options: ["Abrasi", "Sedimentasi", "Deflasi", "Longsor"], answer: 0, solution: "1. Abrasi adalah pengikisan pantai oleh gelombang laut. 2. Sedimentasi justru pengendapan material, kebalikannya. 3. Deflasi itu pengikisan oleh angin di gurun — beda tenaga, beda nama." },
    { q: "Indonesia beriklim tropis dengan dua musim karena....", options: ["Dikelilingi benua yang sangat luas", "Berada di daerah kutub selatan", "Memiliki banyak gunung api", "Terletak di garis khatulistiwa dan dilalui angin muson"], answer: 3, solution: "1. Letak di sekitar khatulistiwa membuat Indonesia panas sepanjang tahun. 2. Angin muson yang berganti arah tiap setengah tahun menciptakan musim hujan dan kemarau. 3. Gunung api tidak menentukan iklim — yang menentukan adalah letak astronomis dan angin." },
    { q: "Angin muson barat bertiup dari Benua Asia menuju Australia pada bulan Oktober-April dan menyebabkan....", options: ["Musim kemarau di Indonesia", "Gelombang dingin dari kutub", "Musim hujan di Indonesia", "Badai topan di Pasifik"], answer: 2, solution: "1. Muson barat berasal dari Asia dan melewati lautan luas sehingga membawa banyak uap air. 2. Uap air itu turun sebagai hujan pada bulan Oktober-April. 3. Banyak yang tertukar: muson barat = hujan, muson timur = kemarau." },
    { q: "Pada bulan April-Oktober, angin muson timur bertiup dari Australia ke Asia sehingga Indonesia mengalami....", options: ["Musim hujan", "Musim kemarau", "Musim semi", "Musim gugur"], answer: 1, solution: "1. Muson timur berasal dari Benua Australia yang kering dan membawa sedikit uap air. 2. Akibatnya hujan berkurang dan terjadilah musim kemarau. 3. Indonesia tidak punya musim semi atau gugur — itu hanya ada di daerah beriklim sedang." },
    { q: "Kota Bogor dijuluki 'Kota Hujan' karena....", options: ["Terletak di tepi pantai", "Dikelilingi gurun pasir", "Berada di daerah bayangan hujan", "Curah hujannya sangat tinggi sepanjang tahun"], answer: 3, solution: "1. Bogor menerima hujan hampir setiap hari dengan curah hujan tahunan sangat tinggi. 2. Letaknya di kaki gunung membuat awan hujan tertahan dan turun di sana. 3. Bukan karena di pantai — justru daerah kaki pegunungan yang basah." },
    { q: "Ketika Indonesia mengalami musim hujan pada bulan Desember, Benua Australia sedang mengalami musim....", options: ["Panas", "Dingin bersalju", "Hujan lebat", "Semi berbunga"], answer: 0, solution: "1. Desember adalah musim panas di belahan bumi selatan, termasuk Australia. 2. Saat itu matahari tepat berada di atas belahan bumi selatan. 3. Musim di Australia kebalikan dari Eropa — jangan disamakan." },
    { q: "Secara geologis, Indonesia terletak pada pertemuan tiga lempeng tektonik besar, yaitu....", options: ["Lempeng Afrika, Amerika, dan Antartika", "Lempeng Arab, India, dan Nazca", "Lempeng Karibia, Scotia, dan Filipina", "Lempeng Indo-Australia, Eurasia, dan Pasifik"], answer: 3, solution: "1. Tiga lempeng itu bertemu tepat di wilayah Indonesia. 2. Tumbukannya membentuk deretan gunung api dan sering memicu gempa. 3. Lempeng Afrika dan Amerika jauh dari Indonesia — tidak ikut menumbuk di sini." },
    { q: "Indonesia sering mengalami gempa dan letusan gunung api karena berada di jalur....", options: ["Sabuk Mediterania saja", "Patahan San Andreas", "Ring of Fire (Cincin Api Pasifik)", "Palung Mariana"], answer: 2, solution: "1. Ring of Fire adalah jalur gunung api aktif yang mengelilingi Samudra Pasifik. 2. Indonesia duduk tepat di jalur ini. 3. Patahan San Andreas ada di Amerika, bukan di Indonesia." },
    { q: "Gempa besar di barat Sumatra terjadi karena Lempeng Indo-Australia....", options: ["Menunjam ke bawah Lempeng Eurasia", "Menjauhi Lempeng Eurasia", "Bergeser ke arah kutub utara", "Berhenti bergerak sepenuhnya"], answer: 0, solution: "1. Lempeng Indo-Australia yang berat menunjam (subduksi) ke bawah Lempeng Eurasia. 2. Gesekan tumbukan inilah yang memicu gempa megathrust. 3. Bukan menjauh — kalau menjauh justru membentuk punggung tengah samudra, bukan gempa besar." },
    { q: "Tsunami dahsyat di Aceh tahun 2004 dipicu oleh....", options: ["Letusan Gunung Krakatau", "Gempa besar di dasar laut", "Badai topan dari Pasifik", "Longsor di pegunungan"], answer: 1, solution: "1. Gempa 9,1 SR di dasar laut barat Sumatra mengangkat dasar laut secara tiba-tiba. 2. Air laut yang terdorong itulah yang menjadi gelombang tsunami. 3. Bukan letusan gunung — tsunami Aceh murni akibat gempa tektonik." },
    { q: "Tanda alam yang menunjukkan tsunami akan datang setelah gempa besar di daerah pantai adalah....", options: ["Langit berubah menjadi hijau", "Burung-burung berkicau ramai", "Angin bertiup sangat sejuk", "Air laut surut sangat jauh tiba-tiba"], answer: 3, solution: "1. Air laut yang surut mendadak berarti massa air sedang tertarik sebelum gelombang besar datang. 2. Inilah tanda paling dikenal untuk segera lari ke dataran tinggi. 3. Langit hijau atau burung berkicau bukan tanda tsunami — jangan menunggu tanda yang salah." },
    { q: "Gunung api paling aktif di Indonesia yang sering meletus hingga kini adalah....", options: ["Gunung Semeru", "Gunung Merapi", "Gunung Kerinci", "Gunung Tambora"], answer: 1, solution: "1. Gunung Merapi di perbatasan Jawa Tengah-DIY meletus berkali-kali dalam sejarah modern. 2. Statusnya dipantau ketat dengan radius bahaya yang jelas. 3. Tambora memang dahsyat tahun 1815, tetapi sudah lama tidur — aktif artinya sering meletus, bukan sekali besar." },
    { q: "Sungai Mekong, sungai terpanjang di Asia Tenggara, mengalir melalui negara-negara....", options: ["Indonesia, Malaysia, dan Singapura", "Thailand, Laos, Kamboja, dan Vietnam", "Filipina, Brunei, dan Timor Leste", "Jepang, Korea, dan Tiongkok"], answer: 1, solution: "1. Sungai Mekong mengalir dari Tiongkok melewati Myanmar, Laos, Thailand, Kamboja, lalu bermuara di Vietnam. 2. Deltanya yang subur ada di Vietnam selatan. 3. Indonesia tidak dilalui Mekong — sungai besar kita adalah Kapuas dan Mahakam." },
    { q: "Satu-satunya negara ASEAN yang tidak memiliki wilayah laut (landlocked) adalah....", options: ["Kamboja", "Myanmar", "Vietnam", "Laos"], answer: 3, solution: "1. Laos terjepit di daratan, dikelilingi Tiongkok, Vietnam, Kamboja, Thailand, dan Myanmar. 2. Karena itu Laos tidak punya pantai dan pelabuhan laut. 3. Kamboja, Myanmar, dan Vietnam semuanya punya garis pantai." },
    { q: "Ibu kota negara Thailand adalah....", options: ["Bangkok", "Chiang Mai", "Phuket", "Pattaya"], answer: 0, solution: "1. Bangkok adalah ibu kota sekaligus kota terbesar Thailand. 2. Chiang Mai dan Phuket adalah kota wisata, bukan ibu kota. 3. Pattaya terkenal sebagai kota pantai — terkenal tidak berarti ibu kota." },
    { q: "Ibu kota negara Kamboja adalah....", options: ["Siem Reap", "Sihanoukville", "Battambang", "Phnom Penh"], answer: 3, solution: "1. Phnom Penh adalah ibu kota Kamboja di tepi Sungai Mekong. 2. Siem Reap terkenal karena candi Angkor Wat, tetapi bukan ibu kota. 3. Kota wisata yang terkenal sering dikira ibu kota — padahal bukan." },
    { q: "Negara kepulauan terbesar di ASEAN sekaligus di dunia adalah....", options: ["Filipina", "Malaysia", "Indonesia", "Thailand"], answer: 2, solution: "1. Indonesia memiliki lebih dari 17.000 pulau, terbanyak di dunia. 2. Filipina juga negara kepulauan, tetapi jumlah pulaunya sekitar 7.600. 3. Malaysia dan Thailand sebagian besar wilayahnya daratan — bukan negara kepulauan murni." },
    { q: "Filipina sering dilanda badai topan karena....", options: ["Terletak di tengah gurun", "Menghadap langsung ke Samudra Pasifik", "Berada di dekat kutub utara", "Dikelilingi pegunungan es"], answer: 1, solution: "1. Filipina berada di jalur badai tropis di sisi barat Samudra Pasifik. 2. Topan terbentuk di atas laut yang hangat lalu menghantam kepulauan ini. 3. Bukan karena gurun — justru karena laut hangat yang luas." },
    { q: "Delta Sungai Mekong yang menjadi lumbung padi utama terletak di negara....", options: ["Laos", "Vietnam", "Myanmar", "Brunei"], answer: 1, solution: "1. Sungai Mekong bermuara dan membentuk delta yang subur di Vietnam selatan. 2. Endapan lumpurnya membuat sawah di sana sangat produktif. 3. Laos memang dilalui Mekong, tetapi deltanya ada di Vietnam — daerah hulu dan hilir itu berbeda." },
    { q: "Dua negara bagian Malaysia yang terletak di Pulau Kalimantan adalah Sabah dan....", options: ["Sarawak", "Johor", "Selangor", "Perak"], answer: 0, solution: "1. Malaysia Timur terdiri dari Sabah dan Sarawak di utara Pulau Kalimantan. 2. Keduanya berbatasan darat langsung dengan Kalimantan Indonesia. 3. Johor, Selangor, dan Perak ada di Semenanjung Malaysia — beda pulau." },
    { q: "Singapura menjadi pusat perdagangan dunia karena letaknya yang strategis di....", options: ["Selat Karimata", "Selat Sunda", "Selat Malaka", "Selat Lombok"], answer: 2, solution: "1. Singapura berada di ujung selatan Selat Malaka, jalur pelayaran tersibuk di dunia. 2. Kapal-kapal dari Asia ke Eropa wajib melewati selat ini. 3. Selat Sunda ada di Indonesia — Singapura tidak berada di sana." },
    { q: "Brunei Darussalam dikenal sebagai negara ASEAN yang kaya raya karena hasil....", options: ["Perkebunan teh", "Pariwisata pantai", "Minyak bumi dan gas alam", "Pertambangan emas"], answer: 2, solution: "1. Brunei memiliki cadangan minyak dan gas alam yang besar di lepas pantainya. 2. Hasil inilah yang membuat pendapatan per kapitanya sangat tinggi. 3. Bukan dari teh atau emas — kekayaannya murni dari migas." },
    { q: "Garis Wallace adalah garis khayal yang memisahkan fauna....", options: ["Australis di barat dan Asiatis di timur", "Kutub utara dan kutub selatan", "Dataran rendah dan dataran tinggi", "Asiatis di barat dan peralihan di tengah Indonesia"], answer: 3, solution: "1. Garis Wallace memisahkan fauna Asiatis (Sumatra, Jawa, Kalimantan) dengan fauna peralihan (Sulawesi, Nusa Tenggara). 2. Garis ini lewat di antara Kalimantan-Sulawesi dan Bali-Lombok. 3. Bukan garis lintang kutub — ini garis persebaran hewan khas Indonesia." },
    { q: "Contoh hewan khas fauna Australis yang hidup di Papua adalah....", options: ["Burung cendrawasih dan kasuari", "Orangutan dan harimau", "Gajah dan badak", "Komodo dan anoa"], answer: 0, solution: "1. Cendrawasih dan kasuari hidup di Papua yang berfauna Australis. 2. Fauna Australis mirip hewan Australia karena dulu daratannya menyatu. 3. Orangutan dan harimau itu fauna Asiatis di barat — kebalikannya." },
    { q: "Hewan yang termasuk fauna Asiatis di Indonesia bagian barat adalah....", options: ["Kanguru pohon", "Burung maleo", "Orangutan dan harimau Sumatra", "Komodo"], answer: 2, solution: "1. Orangutan, harimau Sumatra, gajah, dan bekantan hidup di Sumatra-Kalimantan yang berfauna Asiatis. 2. Fauna ini mirip hewan Asia karena dulu daratannya menyatu dengan Benua Asia. 3. Komodo dan maleo justru fauna peralihan di kawasan tengah — bukan Asiatis." },
    { q: "Komodo yang hanya hidup di Nusa Tenggara termasuk fauna tipe....", options: ["Asiatis", "Australis", "Peralihan (Wallacea)", "Kutub"], answer: 2, solution: "1. Komodo hidup di Pulau Komodo, Rinca, dan Flores — kawasan peralihan (Wallacea). 2. Fauna peralihan memiliki campuran ciri Asiatis dan Australis. 3. Bukan Asiatis murni — komodo tidak ditemukan di Sumatra atau Jawa." },
    { q: "Rafflesia arnoldii yang dijuluki bunga terbesar di dunia banyak ditemukan di....", options: ["Papua", "Kalimantan Timur", "Maluku", "Bengkulu, Sumatra"], answer: 3, solution: "1. Rafflesia arnoldii tumbuh di hutan hujan Sumatra, terutama Bengkulu. 2. Bunganya bisa selebar 1 meter dan berbau busuk seperti bangkai. 3. Banyak yang mengira di Papua karena terdengar eksotis, padahal habitatnya di Sumatra." },
    { q: "Hutan mangrove (bakau) di pesisir pantai berfungsi untuk....", options: ["Tempat menambang pasir", "Mencegah abrasi dan tempat berkembang biak ikan", "Lahan perkebunan kelapa sawit", "Tempat pembuangan sampah"], answer: 1, solution: "1. Akar bakau menahan hempasan gelombang sehingga pantai tidak terkikis (abrasi). 2. Hutan mangrove juga menjadi tempat ikan dan udang berkembang biak. 3. Menebangnya untuk tambak atau sawit justru merusak pantai — fungsinya melindungi, bukan untuk produksi." },
    { q: "Titik di permukaan bumi yang tepat berada di atas pusat gempa (hiposentrum) disebut....", options: ["Episentrum", "Hiposentrum", "Seismograf", "Magma chamber"], answer: 0, solution: "1. Episentrum adalah titik di permukaan bumi tepat di atas pusat gempa. 2. Hiposentrum adalah pusat gempanya sendiri yang berada di dalam bumi. 3. Keduanya sering tertukar — ingat: epi = di atas (permukaan), hipo = di bawah (dalam bumi)." },
    { q: "Nusa Tenggara Timur memiliki musim kemarau yang panjang dan padang sabana karena....", options: ["Terletak di daerah kutub", "Curah hujannya rendah dan dipengaruhi angin kering dari Australia", "Dikelilingi gunung es", "Berada di bawah permukaan laut"], answer: 1, solution: "1. NTT menerima sedikit hujan karena dilalui angin muson timur yang kering dari Australia. 2. Akibatnya padang sabana dan iklim kering mendominasi wilayah ini. 3. Bukan karena kutub — NTT tetap tropis, hanya jauh lebih kering daripada Jawa atau Sumatra." },
    { q: "Sinta membeli tas sekolah model terbaru agar terlihat menarik di antara teman-temannya. Kebutuhan Sinta tersebut termasuk kebutuhan....", options: ["primer", "rohani", "sekunder", "pokok"], answer: 2, solution: "1. Kebutuhan sekunder adalah kebutuhan penunjang yang dipenuhi setelah kebutuhan primer terpenuhi. 2. Tas model terbaru untuk tampil menarik berfungsi menunjang penampilan, bukan untuk bertahan hidup. 3. Jangan terkecoh: tas memang dipakai sekolah, tetapi motif 'agar terlihat menarik' menunjukkan kebutuhan penunjang, bukan kebutuhan pokok." },
    { q: "Kegiatan mendengarkan musik, membaca buku cerita, dan beribadah termasuk kebutuhan....", options: ["rohani", "jasmani", "primer", "sekunder"], answer: 0, solution: "1. Menurut sifatnya, kebutuhan dibagi menjadi jasmani (bersifat materi/fisik) dan rohani (bersifat nonmateri). 2. Musik, bacaan, dan ibadah memberi kepuasan batin yang tidak berwujud benda. 3. Jangan terkecoh: kebutuhan rohani bukan berarti tidak penting — ia tetap kebutuhan, hanya sifatnya nonmateri." },
    { q: "Sebelum membeli sepatu, Dodi membandingkan harga di tiga toko agar mendapat sepatu bagus dengan harga termurah. Sikap Dodi mencerminkan....", options: ["motif ekonomi", "prinsip ekonomi", "tindakan konsumtif", "motif sosial"], answer: 1, solution: "1. Prinsip ekonomi adalah usaha memperoleh hasil sebesar-besarnya dengan pengorbanan sekecil-kecilnya. 2. Dodi berkorban waktu membandingkan harga demi hasil terbaik dengan biaya termurah. 3. Jangan terkecoh: motif ekonomi adalah dorongan/niatnya (misalnya ingin punya sepatu), sedangkan prinsip ekonomi adalah caranya bertindak." },
    { q: "Bu Ratna membuka warung sembako di depan rumahnya agar penghasilan keluarga bertambah. Dorongan Bu Ratna melakukan kegiatan ekonomi tersebut disebut motif....", options: ["mendapat penghargaan", "menolong sesama", "memperoleh kekuasaan", "memenuhi kebutuhan hidup"], answer: 3, solution: "1. Motif ekonomi adalah dorongan dalam diri untuk melakukan kegiatan ekonomi. 2. Bu Ratna berdagang karena ingin menambah penghasilan untuk kebutuhan keluarganya. 3. Jangan terkecoh: membuka warung memang bisa menghasilkan laba, tetapi tujuan utamanya di sini adalah memenuhi kebutuhan hidup keluarga, bukan sekadar mengejar keuntungan sebesar-besarnya." },
    { q: "Pengrajin mengubah balok kayu menjadi meja dan kursi yang siap dipakai. Kegiatan tersebut termasuk produksi karena....", options: ["menyalurkan barang ke konsumen", "menambah nilai guna bentuk barang", "menghabiskan nilai guna barang", "memindahkan barang ke kota"], answer: 1, solution: "1. Produksi adalah kegiatan menciptakan atau menambah nilai guna (utility) barang. 2. Kayu yang diubah menjadi meja mengalami penambahan nilai guna bentuk (form utility). 3. Jangan terkecoh: memindahkan barang antardaerah adalah nilai guna tempat, sedangkan memakai barang sampai habis adalah konsumsi." },
    { q: "Pedagang membeli gabah dari petani di desa, menggilingnya menjadi beras, lalu menjualnya di kota. Nilai guna yang diciptakan dari kegiatan menjual beras di kota adalah nilai guna....", options: ["tempat", "bentuk", "waktu", "kepemilikan"], answer: 0, solution: "1. Nilai guna tempat (place utility) tercipta ketika barang dipindahkan ke lokasi yang lebih membutuhkan. 2. Beras lebih dibutuhkan di kota sehingga harganya lebih tinggi di sana. 3. Jangan terkecoh: menggiling gabah menjadi beras adalah nilai guna bentuk, sedangkan menjual di kota adalah nilai guna tempat." },
    { q: "Bulog menyimpan beras saat panen raya ketika harga murah, lalu menjualnya saat paceklik ketika harga mahal. Tindakan Bulog menciptakan nilai guna....", options: ["bentuk", "waktu", "tempat", "pelayanan"], answer: 1, solution: "1. Nilai guna waktu (time utility) tercipta ketika barang disimpan dan digunakan pada waktu yang lebih tepat. 2. Beras panen raya disimpan untuk dijual saat paceklik. 3. Jangan terkecoh: ini bukan nilai guna tempat karena tidak ada perpindahan lokasi — yang berubah adalah waktunya." },
    { q: "Pak Harto membeli mi instan dalam jumlah sangat besar langsung dari pabrik, lalu menjualnya kembali kepada pemilik warung-warung kecil. Pak Harto berperan sebagai pedagang....", options: ["pengecer", "keliling", "grosir", "kaki lima"], answer: 2, solution: "1. Pedagang grosir membeli barang dalam jumlah besar dari produsen lalu menjualnya kepada pengecer. 2. Pak Harto membeli dari pabrik dan menjual ke warung-warung kecil (pengecer). 3. Jangan terkecoh: pengecer adalah yang menjual langsung kepada konsumen akhir dalam jumlah kecil, seperti warung itu sendiri." },
    { q: "Petani sayur menjual hasil panennya langsung kepada pembeli di pasar tanpa melalui tengkulak. Sistem penyaluran seperti ini disebut distribusi....", options: ["tidak langsung", "semi langsung", "bertahap", "langsung"], answer: 3, solution: "1. Distribusi langsung adalah penyaluran barang dari produsen ke konsumen tanpa perantara. 2. Petani menjual sendiri hasil panennya kepada pembeli. 3. Jangan terkecoh: jika ada tengkulak, agen, atau grosir di antaranya, barulah disebut distribusi tidak langsung." },
    { q: "Andi memakai sepatu olahraganya setiap hari hingga solnya tipis dan tidak layak pakai. Kegiatan Andi tersebut termasuk kegiatan....", options: ["produksi", "konsumsi", "distribusi", "investasi"], answer: 1, solution: "1. Konsumsi adalah kegiatan menggunakan atau menghabiskan nilai guna barang dan jasa. 2. Sepatu dipakai terus-menerus hingga nilai gunanya habis. 3. Jangan terkecoh: membeli sepatu adalah konsumsi juga, tetapi 'memakai hingga rusak' menegaskan habisnya nilai guna barang." },
    { q: "Di pabrik roti, karyawan yang menguleni adonan dan mengoperasikan oven termasuk faktor produksi....", options: ["tenaga kerja", "alam", "modal", "konsumen"], answer: 0, solution: "1. Faktor produksi terdiri dari alam, tenaga kerja, modal, dan kewirausahaan. 2. Karyawan menyumbang tenaga dan keterampilannya dalam proses produksi. 3. Jangan terkecoh: oven dan bangunan pabrik adalah faktor modal, sedangkan terigu dan gula adalah faktor alam (bahan baku)." },
    { q: "Seseorang yang berani mengambil risiko mendirikan usaha, mengatur seluruh faktor produksi, dan bertanggung jawab atas untung ruginya disebut....", options: ["distributor", "konsumen", "wirausahawan", "kreditor"], answer: 2, solution: "1. Faktor produksi kewirausahaan (entrepreneurship) adalah kemampuan mengatur dan mengambil risiko usaha. 2. Orang yang mendirikan dan mengelola usaha dengan menanggung risikonya adalah wirausahawan. 3. Jangan terkecoh: distributor hanya menyalurkan barang, sedangkan kreditor adalah pihak yang memberi pinjaman." },
    { q: "Rumah tangga yang membeli faktor produksi lalu mengolahnya menjadi barang dan jasa yang siap dikonsumsi adalah rumah tangga....", options: ["keluarga", "perusahaan", "pemerintah", "luar negeri"], answer: 1, solution: "1. Rumah tangga perusahaan (produsen) berperan mengombinasikan faktor produksi menjadi barang dan jasa. 2. Ia membeli tanah, tenaga kerja, dan modal, lalu menghasilkan produk. 3. Jangan terkecoh: rumah tangga keluarga justru berperan sebaliknya — sebagai pemilik faktor produksi dan pembeli barang jadi." },
    { q: "Setiap bulan ayah membayar pajak penghasilan yang dipotong dari gajinya. Pajak yang dikumpulkan pemerintah tersebut terutama digunakan untuk....", options: ["membiayai pembangunan dan pelayanan publik", "menambah modal usaha swasta", "membayar utang perusahaan", "modal kampanye pejabat"], answer: 0, solution: "1. Salah satu peran pemerintah sebagai pelaku ekonomi adalah menarik pajak dari masyarakat. 2. Dana pajak dipakai untuk pembangunan infrastruktur dan layanan publik seperti jalan, sekolah, dan rumah sakit. 3. Jangan terkecoh: pajak bukan untuk memperkaya pejabat atau memodali perusahaan swasta — ia kembali ke masyarakat dalam bentuk pembangunan." },
    { q: "Indonesia menjual biji kopi ke Jepang, sedangkan Jepang menjual mesin ke Indonesia. Dalam perdagangan ini, Jepang berperan sebagai rumah tangga....", options: ["keluarga", "perusahaan", "luar negeri", "pemerintah"], answer: 2, solution: "1. Pelaku ekonomi terdiri dari rumah tangga keluarga, perusahaan, pemerintah, dan luar negeri. 2. Jepang adalah negara lain yang bertransaksi ekonomi dengan Indonesia. 3. Jangan terkecoh: meski perusahaannya yang mengekspor, dalam lingkup negara ia dikelompokkan sebagai rumah tangga luar negeri." },
    { q: "Pasar tradisional tempat penjual dan pembeli bertemu langsung untuk tawar-menawar harga cabai disebut pasar....", options: ["abstrak", "konkret", "maya", "gelap"], answer: 1, solution: "1. Menurut wujudnya, pasar dibedakan menjadi konkret dan abstrak. 2. Pasar konkret mempertemukan penjual dan pembeli secara langsung di satu tempat. 3. Jangan terkecoh: pasar abstrak justru kebalikannya — penjual dan pembeli tidak bertemu langsung, misalnya jual beli lewat internet." },
    { q: "Ibu memesan baju melalui aplikasi belanja online dan membayarnya dengan transfer bank tanpa pernah bertemu penjualnya. Transaksi tersebut terjadi di pasar....", options: ["konkret", "tradisional", "harian", "abstrak"], answer: 3, solution: "1. Pasar abstrak adalah pasar yang penjual dan pembelinya tidak bertemu secara langsung. 2. Jual beli online hanya mempertemukan barang dan data, bukan orangnya. 3. Jangan terkecoh: 'pasar' di sini bukan bangunannya, melainkan proses bertemunya permintaan dan penawaran — yang bisa terjadi lewat layar ponsel." },
    { q: "Pasar malam yang hanya dibuka selama ada perayaan HUT kota termasuk jenis pasar menurut waktu, yaitu pasar....", options: ["temporer", "harian", "mingguan", "bulanan"], answer: 0, solution: "1. Menurut waktu penyelenggaraannya, pasar dibedakan menjadi harian, mingguan, bulanan, tahunan, dan temporer. 2. Pasar temporer hanya ada pada waktu-waktu tertentu yang tidak tetap. 3. Jangan terkecoh: pasar tahunan seperti Pekan Raya Jakarta waktunya tetap setiap tahun, sedangkan pasar malam perayaan waktunya tidak menentu." },
    { q: "Pameran mesin pertanian tempat para pengusaha pabrik membeli traktor dan peralatan produksi termasuk pasar....", options: ["barang konsumsi", "barang jadi", "faktor produksi", "eceran"], answer: 2, solution: "1. Menurut barang yang diperdagangkan, pasar dibedakan menjadi pasar barang konsumsi dan pasar faktor produksi. 2. Traktor dan mesin adalah barang modal untuk berproduksi, bukan untuk dikonsumsi langsung. 3. Jangan terkecoh: meski pembelinya pengusaha, yang diperdagangkan adalah faktor produksi (modal), bukan barang konsumsi." },
    { q: "Di suatu daerah hanya ada satu perusahaan listrik sehingga masyarakat tidak punya pilihan pemasok lain. Struktur pasar seperti ini disebut pasar....", options: ["persaingan sempurna", "monopoli", "oligopoli", "konkret"], answer: 1, solution: "1. Menurut strukturnya, pasar dibedakan antara lain menjadi persaingan sempurna dan monopoli. 2. Monopoli adalah pasar yang dikuasai satu penjual/produsen saja. 3. Jangan terkecoh: oligopoli dikuasai beberapa penjual, sedangkan persaingan sempurna memiliki banyak penjual dan pembeli." },
    { q: "Menurut hukum permintaan, jika harga cabai naik tajam di pasar maka....", options: ["jumlah cabai yang diminta menurun", "jumlah cabai yang diminta meningkat", "penawaran cabai ikut menurun", "harga cabai kembali turun"], answer: 0, solution: "1. Hukum permintaan menyatakan: semakin tinggi harga, semakin sedikit jumlah barang yang diminta (ceteris paribus). 2. Konsumen mengurangi pembelian cabai atau mencari pengganti saat harganya mahal. 3. Jangan terkecoh: yang berubah karena harga naik adalah jumlah yang diminta, bukan jumlah yang ditawarkan — penawaran justru cenderung naik." },
    { q: "Menurut hukum penawaran, jika harga beras naik maka petani cenderung....", options: ["menimbun beras di rumah", "beralih menanam palawija", "mengurangi luas sawah", "menawarkan beras lebih banyak"], answer: 3, solution: "1. Hukum penawaran menyatakan: semakin tinggi harga, semakin banyak jumlah barang yang ditawarkan (ceteris paribus). 2. Harga tinggi memberi untung lebih besar sehingga produsen menambah pasokan. 3. Jangan terkecoh: hukum penawaran membahas perilaku penjual/produsen, sedangkan perilaku pembeli diatur hukum permintaan." },
    { q: "Berikut ini yang BUKAN merupakan faktor yang memengaruhi permintaan suatu barang adalah....", options: ["pendapatan konsumen", "selera konsumen", "biaya produksi", "harga barang pengganti"], answer: 2, solution: "1. Faktor yang memengaruhi permintaan antara lain harga barang, pendapatan, selera, harga barang lain, dan jumlah penduduk. 2. Biaya produksi memengaruhi keputusan produsen, bukan keinginan konsumen membeli. 3. Jangan terkecoh: biaya produksi adalah faktor penawaran — ia menentukan berapa banyak barang yang sanggup dijual produsen pada suatu harga." },
    { q: "Ketika harga daging sapi naik, banyak keluarga beralih membeli daging ayam. Daging ayam bagi daging sapi merupakan barang....", options: ["komplementer", "substitusi", "mewah", "inferior"], answer: 1, solution: "1. Barang substitusi (pengganti) adalah barang yang dapat saling menggantikan fungsinya. 2. Kenaikan harga daging sapi menaikkan permintaan daging ayam sebagai penggantinya. 3. Jangan terkecoh: barang komplementer justru kebalikannya — dipakai bersama-sama sehingga kenaikan harga salah satunya menurunkan permintaan yang lain." },
    { q: "Gula dan teh biasanya dikonsumsi bersama-sama. Jika harga gula naik tajam, permintaan terhadap teh kemungkinan akan....", options: ["menurun", "meningkat", "tetap", "berlipat ganda"], answer: 0, solution: "1. Barang komplementer (pelengkap) adalah barang yang penggunaannya saling melengkapi. 2. Teh terasa kurang nikmat tanpa gula, sehingga orang mengurangi konsumsi keduanya saat gula mahal. 3. Jangan terkecoh: ini kebalikan dari barang substitusi — pada barang pelengkap, harga yang satu naik membuat permintaan pasangannya turun." },
    { q: "Harga yang terbentuk pada titik bertemunya kurva permintaan dan kurva penawaran sehingga jumlah yang diminta sama dengan jumlah yang ditawarkan disebut harga....", options: ["pokok", "eceran", "grosir", "keseimbangan"], answer: 3, solution: "1. Pada titik temu permintaan dan penawaran, tidak ada kelebihan permintaan maupun kelebihan penawaran. 2. Harga pada titik inilah yang disepakati pasar, disebut harga keseimbangan (equilibrium). 3. Jangan terkecoh: harga pokok adalah biaya pembuatan barang, sedangkan harga eceran/grosir adalah tingkat harga menurut jumlah pembelian." },
    { q: "Fungsi asli uang sebagai alat pembayaran adalah....", options: ["penimbun kekayaan dan pemindah kekayaan", "alat tukar dan satuan hitung", "alat pembayaran utang dan standar cicilan", "alat tukar dan alat politik"], answer: 1, solution: "1. Fungsi asli (primer) uang adalah sebagai alat tukar (medium of exchange) dan satuan hitung (unit of account). 2. Uang memudahkan barter menjadi jual beli dan menjadi ukuran nilai barang. 3. Jangan terkecoh: penimbun kekayaan, pemindah kekayaan, dan alat pembayaran utang adalah fungsi turunan uang, bukan fungsi aslinya." },
    { q: "Cek, giro, dan transfer antarbank yang disimpan masyarakat di bank termasuk jenis uang....", options: ["giral", "kartal", "logam", "kertas"], answer: 0, solution: "1. Uang dibedakan menjadi kartal (kertas dan logam) dan giral (simpanan di bank). 2. Cek dan giro adalah alat penarikan atas simpanan di bank, bukan uang fisik. 3. Jangan terkecoh: uang kertas dan logam adalah uang kartal karena beredar langsung di tangan masyarakat." },
    { q: "Di Indonesia, satu-satunya lembaga yang berhak mencetak dan mengedarkan uang kartal rupiah adalah....", options: ["bank umum", "Bank Indonesia", "pegadaian", "koperasi simpan pinjam"], answer: 1, solution: "1. Bank Indonesia adalah bank sentral Republik Indonesia. 2. Salah satu tugas bank sentral adalah mengatur peredaran uang, termasuk hak tunggal mencetak uang kartal. 3. Jangan terkecoh: bank umum hanya menghimpun dana dan memberi kredit — ia tidak boleh mencetak uang sendiri." },
    { q: "Fungsi utama bank umum dalam kegiatan ekonomi adalah....", options: ["menghimpun dana masyarakat dan menyalurkannya sebagai kredit", "mencetak uang kartal", "menarik pajak dari nasabah", "mengatur nilai tukar rupiah"], answer: 0, solution: "1. Bank umum berperan sebagai perantara keuangan (financial intermediary). 2. Ia menghimpun tabungan, deposito, dan giro lalu menyalurkannya kembali sebagai kredit usaha. 3. Jangan terkecoh: mencetak uang dan menjaga kestabilan rupiah adalah tugas Bank Indonesia sebagai bank sentral, bukan bank umum." },
    { q: "PT Kereta Api Indonesia (KAI) dan PT PLN (Persero) termasuk jenis badan usaha....", options: ["BUMS", "koperasi", "BUMD", "BUMN"], answer: 3, solution: "1. Badan usaha milik negara (BUMN) adalah perusahaan yang sebagian besar modalnya dimiliki negara. 2. KAI dan PLN berbentuk Persero yang sahamnya dimiliki pemerintah Indonesia. 3. Jangan terkecoh: BUMD milik pemerintah daerah (misalnya PDAM), sedangkan BUMS milik swasta." },
    { q: "Perusahaan Daerah Air Minum (PDAM) yang melayani kebutuhan air bersih suatu kabupaten termasuk badan usaha....", options: ["BUMN", "BUMS", "BUMD", "koperasi"], answer: 2, solution: "1. BUMD adalah badan usaha yang modalnya dimiliki oleh pemerintah daerah. 2. PDAM didirikan dan dimiliki oleh pemerintah kabupaten/kota. 3. Jangan terkecoh: meski sama-sama milik pemerintah, BUMN milik pemerintah pusat sedangkan BUMD milik pemerintah daerah." },
    { q: "Dalam rapat anggota koperasi, Pak Budi yang simpanannya kecil memiliki hak suara yang sama dengan anggota yang simpanannya besar. Hal ini mencerminkan prinsip koperasi, yaitu....", options: ["kekeluargaan", "demokrasi", "kesejahteraan", "gotong royong"], answer: 1, solution: "1. Koperasi berasaskan kekeluargaan dan berprinsip demokrasi: satu anggota satu suara. 2. Hak suara tidak ditentukan oleh besarnya modal/simpanan anggota. 3. Jangan terkecoh: 'kekeluargaan' adalah asas koperasi, sedangkan persamaan hak suara adalah wujud prinsip demokrasinya." },
    { q: "Sisa Hasil Usaha (SHU) koperasi pada akhir tahun dibagikan kepada anggota dengan pembagian terbesar diberikan kepada anggota yang....", options: ["paling aktif bertransaksi di koperasi", "paling lama menjadi anggota", "jabatannya pengurus", "simpanannya paling sedikit"], answer: 0, solution: "1. SHU adalah pendapatan koperasi dikurangi biaya-biaya dalam satu tahun buku. 2. SHU dibagikan sebanding dengan jasa/transaksi masing-masing anggota terhadap koperasi. 3. Jangan terkecoh: SHU bukan dibagi rata atau berdasarkan lamanya keanggotaan — yang rajin berbelanja/memakai jasa koperasi mendapat bagian lebih besar." },
    { q: "Indonesia membeli gandum dari Australia karena tidak dapat memproduksinya sendiri dalam jumlah cukup. Kegiatan membeli barang dari luar negeri tersebut disebut....", options: ["ekspor", "devisa", "impor", "barter"], answer: 2, solution: "1. Perdagangan internasional terdiri dari ekspor (menjual ke luar negeri) dan impor (membeli dari luar negeri). 2. Indonesia membeli gandum dari Australia untuk dipakai di dalam negeri. 3. Jangan terkecoh: ekspor adalah kebalikannya — menjual barang ke luar negeri, seperti Indonesia menjual kopi ke Jepang." },
    { q: "Devisa negara adalah....", options: ["pajak dari barang impor", "alat pembayaran luar negeri yang diakui internasional", "utang pemerintah ke bank", "uang kartal rupiah"], answer: 1, solution: "1. Devisa adalah segala alat pembayaran luar negeri (valuta asing) yang dapat diterima dalam perdagangan internasional. 2. Contohnya dolar AS hasil ekspor yang dipakai membayar impor. 3. Jangan terkecoh: rupiah hanya berlaku di dalam negeri, sedangkan pajak impor adalah penerimaan negara dalam rupiah — keduanya bukan devisa." },
    { q: "Berikut ini yang merupakan sumber devisa negara Indonesia adalah....", options: ["penjualan di pasar tradisional", "pajak penghasilan warga", "APBD provinsi", "hasil ekspor dan kunjungan wisatawan asing"], answer: 3, solution: "1. Devisa masuk ke negara antara lain dari hasil ekspor barang, jasa pariwisata, dan kiriman tenaga kerja di luar negeri. 2. Ekspor kopi dan belanja wisatawan asing menambah cadangan valuta asing Indonesia. 3. Jangan terkecoh: pajak dan APBD adalah keuangan dalam negeri (rupiah), sedangkan pasar tradisional tidak melibatkan pembayaran luar negeri." },
    { q: "Pada tahun tertentu nilai ekspor Indonesia tercatat lebih besar daripada nilai impornya. Kondisi neraca perdagangan Indonesia saat itu disebut....", options: ["surplus", "defisit", "bangkrut", "inflasi"], answer: 0, solution: "1. Neraca perdagangan membandingkan nilai ekspor dan impor suatu negara. 2. Ekspor lebih besar dari impor berarti perdagangan mengalami surplus (positif). 3. Jangan terkecoh: jika impor yang lebih besar dari ekspor, barulah disebut defisit — kebalikan dari surplus." },
    { q: "Bangsa Eropa pertama yang datang ke Indonesia adalah Portugis. Pada tahun 1511 mereka berhasil menguasai Malaka di bawah pimpinan....", options: ["Vasco da Gama", "Alfonso d'Albuquerque", "Ferdinand Magellan", "Christopher Columbus"], answer: 1, solution: "1. Portugis tiba di Asia Tenggara untuk mencari rempah-rempah dan menyebarkan agama. 2. Pada 1511 armada Portugis pimpinan Alfonso d'Albuquerque menaklukkan Malaka, pusat perdagangan rempah. 3. Jangan tertukar dengan Vasco da Gama yang hanya sampai India (1498), bukan Indonesia." },
    { q: "Perjanjian Saragosa yang ditandatangani pada tahun 1529 membagi wilayah kekuasaan di belahan bumi timur antara....", options: ["Inggris dan Belanda", "Belanda dan Portugis", "Prancis dan Inggris", "Spanyol dan Portugis"], answer: 3, solution: "1. Spanyol dan Portugis berebut wilayah rempah-rempah di Maluku. 2. Perjanjian Saragosa (1529) menetapkan Maluku untuk Portugis dan Filipina untuk Spanyol. 3. Jangan tertukar dengan Perjanjian Tordesillas (1494) yang membagi belahan bumi barat." },
    { q: "Pada masa pemerintahan Inggris di Indonesia (1811–1816), Thomas Stamford Raffles menerapkan sistem....", options: ["tanam paksa", "sewa tanah (land rent)", "kerja rodi", "politik etis"], answer: 1, solution: "1. Raffles beranggapan tanah adalah milik pemerintah sehingga rakyat wajib membayar sewa. 2. Sistem sewa tanah (land rent) inilah yang ia terapkan selama berkuasa. 3. Tanam paksa adalah kebijakan Van den Bosch (1830) dan kerja rodi adalah kebijakan Daendels, bukan Raffles." },
    { q: "VOC dibubarkan pada 31 Desember 1799. Salah satu penyebab utama keruntuhannya adalah....", options: ["kalah perang melawan Portugis di Maluku", "ditemukannya jalur pelayaran baru ke Amerika", "korupsi para pegawai dan utang yang menumpuk", "seluruh rakyat Indonesia bersatu melawannya"], answer: 2, solution: "1. VOC mengalami kemunduran karena pegawai banyak yang korupsi dan biaya perang yang besar. 2. Utang VOC menumpuk hingga kasnya kosong dan tidak mampu membayar. 3. Bukan karena serangan militer rakyat, melainkan kebangkrutan akibat tata kelola yang buruk." },
    { q: "Istilah 'kerja rodi' pada masa penjajahan berkaitan dengan kebijakan Gubernur Jenderal....", options: ["Herman Willem Daendels", "Thomas Stamford Raffles", "Johannes van den Bosch", "Janssens"], answer: 0, solution: "1. Daendels memerintah 1808–1811 dan membutuhkan pembangunan pertahanan secara cepat. 2. Ia memaksa rakyat membangun Jalan Raya Pos Anyer–Panarukan tanpa upah, inilah kerja rodi. 3. Jangan tertukar dengan Raffles (sewa tanah) atau Van den Bosch (tanam paksa)." },
    { q: "Dalam sistem tanam paksa (Cultuurstelsel) tahun 1830, rakyat wajib menyerahkan .... tanahnya untuk ditanami tanaman ekspor seperti kopi dan tebu.", options: ["seluruh", "setengah", "seperlima (20%)", "sepersepuluh (10%)"], answer: 2, solution: "1. Aturan Cultuurstelsel mewajibkan rakyat menyediakan seperlima tanahnya untuk tanaman wajib. 2. Praktiknya sering melebihi ketentuan sehingga rakyat menderita kelaparan. 3. Ingat angkanya: seperlima tanah dan seperlima waktu kerja, bukan setengah atau seluruhnya." },
    { q: "Novel Max Havelaar (1860) karya Multatuli (Eduard Douwes Dekker) berisi kritik tajam terhadap....", options: ["perdagangan rempah VOC di Maluku", "kekejaman Jepang pada masa romusha", "monopoli dagang Inggris di India", "penderitaan rakyat akibat tanam paksa"], answer: 3, solution: "1. Multatuli pernah menjadi asisten residen di Lebak, Banten, dan menyaksikan langsung penderitaan rakyat. 2. Novelnya membuka mata publik Belanda tentang kesewenang-wenangan tanam paksa. 3. Kritiknya ditujukan pada pemerintah kolonial Belanda, bukan pada Jepang atau VOC." },
    { q: "Sarekat Dagang Islam, cikal bakal Sarekat Islam, didirikan di Solo pada tahun 1905 oleh....", options: ["H.O.S. Tjokroaminoto", "Haji Samanhudi", "Ki Hajar Dewantara", "R.M. Tirto Adhi Soerjo"], answer: 1, solution: "1. Para pedagang batik pribumi di Laweyan, Solo, merasa tersaingi pedagang Tionghoa. 2. Haji Samanhudi menghimpun mereka dalam Sarekat Dagang Islam (1905) yang pada 1912 menjadi Sarekat Islam. 3. Tjokroaminoto adalah pemimpin Sarekat Islam setelahnya, bukan pendiri SDI." },
    { q: "Partai Nasional Indonesia (PNI) yang didirikan Soekarno di Bandung pada 4 Juli 1927 berlandaskan asas....", options: ["nonkooperasi, menolak bekerja sama dengan pemerintah kolonial", "kooperasi, bekerja sama dengan pemerintah kolonial", "netral, tidak memihak siapa pun", "federalisme, mendukung negara boneka Belanda"], answer: 0, solution: "1. PNI bertujuan mencapai Indonesia merdeka dengan kekuatan rakyat sendiri. 2. Karena itu PNI menolak duduk di Volksraad dan tidak mau bekerja sama dengan Belanda (nonkooperasi). 3. Kebalikannya adalah asas kooperasi yang dianut organisasi moderat seperti Parindra." },
    { q: "Kongres Pemuda II yang menghasilkan ikrar Sumpah Pemuda pada 27–28 Oktober 1928 dipimpin oleh....", options: ["Ir. Soekarno", "Mohammad Yamin", "Soegondo Djojopoespito", "Wage Rudolf Supratman"], answer: 2, solution: "1. Kongres Pemuda II diselenggarakan oleh PPPI (Perhimpunan Pelajar-Pelajar Indonesia). 2. Ketua panitianya adalah Soegondo Djojopoespito. 3. Mohammad Yamin adalah perumus teks Sumpah Pemuda, sedangkan W.R. Supratman pencipta lagu Indonesia Raya." },
    { q: "Janji kemerdekaan Indonesia oleh pemerintah Jepang disampaikan oleh Perdana Menteri Koiso pada....", options: ["8 Maret 1942", "7 September 1944", "1 Maret 1945", "17 Agustus 1945"], answer: 1, solution: "1. Setelah Jepang terdesak dalam Perang Pasifik, mereka butuh simpati rakyat Indonesia. 2. PM Koiso mengumumkan janji kemerdekaan pada 7 September 1944. 3. Jangan tertukar dengan 8 Maret 1942 (Belanda menyerah kepada Jepang) atau 1 Maret 1945 (BPUPKI dibentuk)." },
    { q: "Naskah proklamasi yang ditulis tangan oleh Soekarno kemudian diketik oleh....", options: ["B.M. Diah", "Sukarni", "Achmad Soebardjo", "Sayuti Melik"], answer: 3, solution: "1. Setelah disusun di rumah Laksamana Maeda, naskah tulisan tangan Soekarno perlu diketik rapi. 2. Tugas itu dilakukan oleh Sayuti Melik pada dini hari 17 Agustus 1945. 3. B.M. Diah dan Sukarni adalah tokoh pemuda yang hadir, bukan pengetik naskah." },
    { q: "Pertempuran besar pada 10 November 1945 di Surabaya setiap tahun diperingati sebagai....", options: ["Hari Kemerdekaan", "Hari Pahlawan", "Hari Bela Negara", "Hari Juang Kartika"], answer: 1, solution: "1. Rakyat Surabaya di bawah orasi Bung Tomo menolak ultimatum Sekutu dan bertempur habis-habisan. 2. Semangat juang itu diabadikan sebagai Hari Pahlawan setiap 10 November. 3. Hari Kemerdekaan adalah 17 Agustus, sedangkan Hari Bela Negara diperingati 19 Desember." },
    { q: "Pertempuran Ambarawa (20 November–15 Desember 1945) dimenangkan pasukan Indonesia yang dipimpin oleh....", options: ["Kolonel Soedirman", "Bung Tomo", "Jenderal A.H. Nasution", "Brigjen Slamet Riyadi"], answer: 0, solution: "1. Pasukan Sekutu/NICA mendarat di Semarang lalu bergerak ke Ambarawa dan Magelang. 2. Kolonel Soedirman memimpin serangan dengan strategi supit urang (pengepungan dari dua sisi). 3. Bung Tomo adalah tokoh pertempuran Surabaya, bukan Ambarawa." },
    { q: "Tokoh yang gugur dalam peristiwa Bandung Lautan Api saat meledakkan gudang mesiu di Dayeuhkolot adalah....", options: ["Sutan Sjahrir", "I Gusti Ngurah Rai", "Mohammad Toha", "Robert Wolter Mongisidi"], answer: 2, solution: "1. Pada 24 Maret 1946 rakyat dan TRI membakar Bandung bagian selatan agar tidak dikuasai Sekutu. 2. Mohammad Toha bersama Ramdan gugur saat meledakkan gudang amunisi agar tidak jatuh ke tangan musuh. 3. I Gusti Ngurah Rai gugur dalam Puputan Margarana di Bali, bukan di Bandung." },
    { q: "Akibat Agresi Militer Belanda II (19 Desember 1948) yang menduduki Yogyakarta, didirikan pemerintahan darurat di Bukittinggi yang dikenal sebagai....", options: ["Republik Indonesia Serikat", "Pemerintah Darurat Republik Indonesia (PDRI)", "Negara Indonesia Timur", "Republik Maluku Selatan"], answer: 1, solution: "1. Soekarno dan Hatta ditangkap Belanda saat Yogyakarta diserbu. 2. Syafruddin Prawiranegara membentuk PDRI di Bukittinggi agar Indonesia tetap punya pemerintahan yang sah. 3. RIS adalah hasil KMB setahun kemudian, bukan pemerintahan darurat ini." },
    { q: "Sex ratio adalah perbandingan jumlah penduduk....", options: ["usia muda terhadap usia tua", "perempuan terhadap 100 penduduk laki-laki", "laki-laki terhadap 100 penduduk perempuan", "desa terhadap kota"], answer: 2, solution: "1. Sex ratio dihitung dengan rumus (jumlah laki-laki : jumlah perempuan) x 100. 2. Artinya angka ini menunjukkan berapa penduduk laki-laki untuk setiap 100 penduduk perempuan. 3. Jangan dibalik: pembandingnya selalu 100 penduduk perempuan." },
    { q: "Penduduk yang termasuk angkatan kerja adalah....", options: ["berusia 15 tahun ke atas yang bekerja atau sedang mencari pekerjaan", "seluruh penduduk berusia 0–14 tahun", "hanya pegawai negeri dan TNI/Polri", "penduduk yang sudah pensiun dan tidak bekerja"], answer: 0, solution: "1. Angkatan kerja adalah penduduk usia kerja (15 tahun ke atas) yang aktif secara ekonomi. 2. Termasuk yang sudah bekerja maupun yang menganggur tetapi sedang mencari pekerjaan. 3. Anak-anak dan lansia yang tidak bekerja tidak termasuk angkatan kerja." },
    { q: "Kelompok usia produktif menurut Badan Pusat Statistik (BPS) adalah penduduk berusia....", options: ["0–14 tahun", "10–20 tahun", "65 tahun ke atas", "15–64 tahun"], answer: 3, solution: "1. Usia produktif adalah rentang usia yang dianggap mampu bekerja dan menghasilkan. 2. BPS menetapkannya pada 15–64 tahun. 3. Usia 0–14 tahun disebut usia belum produktif, sedangkan 65 tahun ke atas adalah usia tidak produktif." },
    { q: "Masuknya warga negara asing ke Indonesia untuk menetap disebut....", options: ["urbanisasi", "imigrasi", "emigrasi", "transmigrasi"], answer: 1, solution: "1. Migrasi dibedakan berdasarkan arah perpindahannya. 2. Masuknya penduduk asing ke dalam negeri disebut imigrasi (im = masuk). 3. Kebalikannya, keluarnya WNI ke luar negeri, disebut emigrasi." },
    { q: "Tujuan utama program transmigrasi yang dilaksanakan pemerintah Indonesia adalah....", options: ["memperbanyak penduduk di Pulau Jawa", "pemerataan persebaran penduduk dan peningkatan kesejahteraan", "menarik wisatawan asing ke daerah transmigran", "memindahkan ibu kota ke Kalimantan"], answer: 1, solution: "1. Penduduk Indonesia menumpuk di Jawa sementara pulau lain jarang penduduknya. 2. Transmigrasi memindahkan penduduk ke luar Jawa agar persebaran merata dan lahan luar Jawa tergarap. 3. Bukan untuk menambah penduduk Jawa, justru sebaliknya mengurangi kepadatannya." },
    { q: "Salah satu indikator yang menunjukkan tingkat kesehatan penduduk suatu negara adalah....", options: ["angka harapan hidup", "angka kelahiran yang tinggi", "kepadatan penduduk", "jumlah angkatan kerja"], answer: 0, solution: "1. Kualitas penduduk diukur dari pendidikan, kesehatan, dan pendapatan. 2. Angka harapan hidup yang tinggi menandakan pelayanan kesehatan yang baik. 3. Angka kelahiran tinggi justru menunjukkan laju pertumbuhan penduduk, bukan kesehatannya." },
    { q: "Dampak positif jumlah penduduk yang besar bagi pembangunan nasional adalah....", options: ["berkurangnya kebutuhan pangan nasional", "punahnya budaya daerah", "tersedianya tenaga kerja yang melimpah", "menurunnya angka pengangguran otomatis"], answer: 2, solution: "1. Penduduk yang banyak berarti sumber daya manusia yang banyak pula. 2. Jika dikelola dengan pendidikan yang baik, mereka menjadi tenaga kerja dan pasar yang besar. 3. Jumlah besar tidak otomatis mengurangi pengangguran; tanpa lapangan kerja justru menambahnya." },
    { q: "Angka beban ketergantungan (dependency ratio) dihitung dengan membandingkan....", options: ["penduduk kota dengan penduduk desa", "penduduk usia nonproduktif dengan penduduk usia produktif", "penduduk laki-laki dengan penduduk perempuan", "angka kelahiran dengan angka kematian"], answer: 1, solution: "1. Beban ketergantungan mengukur berapa orang yang ditanggung oleh penduduk produktif. 2. Rumusnya: (usia 0–14 + 65 ke atas) dibagi usia 15–64, dikali 100. 3. Bukan perbandingan jenis kelamin (itu sex ratio) atau kota-desa." },
    { q: "Pertumbuhan penduduk alami diperoleh dari....", options: ["jumlah imigran dikurangi emigran", "selisih angka kelahiran dan angka kematian", "sensus penduduk setiap sepuluh tahun", "perpindahan penduduk desa ke kota"], answer: 1, solution: "1. Pertumbuhan alami hanya memperhitungkan peristiwa kelahiran dan kematian. 2. Rumusnya sederhana: angka kelahiran dikurangi angka kematian, tanpa melibatkan migrasi. 3. Jika migrasi ikut dihitung, namanya menjadi pertumbuhan penduduk total." },
    { q: "Upaya pemerintah untuk meningkatkan kualitas penduduk di bidang pendidikan adalah melalui....", options: ["program wajib belajar 12 tahun", "program transmigrasi bedol desa", "pembangunan jalan tol antarprovinsi", "pemberian bantuan modal usaha tani"], answer: 0, solution: "1. Kualitas penduduk sangat ditentukan oleh tingkat pendidikannya. 2. Program wajib belajar 12 tahun memastikan anak Indonesia bersekolah minimal hingga SMA. 3. Transmigrasi dan jalan tol berkaitan dengan persebaran dan infrastruktur, bukan kualitas pendidikan." },
    { q: "Dampak negatif urbanisasi yang tidak terkendali di kota-kota besar adalah....", options: ["bertambahnya lahan pertanian di kota", "menurunnya harga tanah perkotaan", "munculnya permukiman kumuh dan pengangguran", "berkurangnya kemacetan lalu lintas"], answer: 2, solution: "1. Urbanisasi adalah perpindahan penduduk desa ke kota yang umumnya tidak diimbangi lapangan kerja. 2. Akibatnya muncul permukiman kumuh, pengangguran, dan kemacetan di kota. 3. Lahan pertanian justru berkurang karena alih fungsi lahan di perkotaan." },
    { q: "Istilah globalisasi berasal dari kata 'global' yang berarti....", options: ["terbatas pada satu negara", "mendunia dan tanpa batas antarnegara", "kembali ke tradisi lama", "hanya berkaitan dengan teknologi"], answer: 1, solution: "1. Kata global merujuk pada globe atau bola dunia secara keseluruhan. 2. Globalisasi adalah proses mendunianya seluruh aspek kehidupan sehingga batas antarnegara seolah hilang. 3. Bukan sekadar teknologi; ekonomi, budaya, dan sosial pun ikut mendunia." },
    { q: "Berikut ini yang merupakan contoh globalisasi di bidang ekonomi adalah....", options: ["masyarakat memakai batik ke kantor", "gotong royong membersihkan desa", "perusahaan asing menanamkan modal di Indonesia", "upacara adat yang disiarkan televisi lokal"], answer: 2, solution: "1. Globalisasi ekonomi ditandai aliran modal, barang, dan jasa lintas negara. 2. Investasi perusahaan asing (misalnya pabrik otomotif Jepang) adalah contoh nyatanya. 3. Memakai batik dan gotong royong adalah budaya lokal, bukan globalisasi ekonomi." },
    { q: "Contoh globalisasi di bidang budaya yang mudah dijumpai remaja Indonesia adalah....", options: ["merebaknya budaya K-pop dan makanan cepat saji", "musyawarah memilih ketua RT", "panen raya padi di sawah", "penggunaan bahasa daerah di rumah"], answer: 0, solution: "1. Globalisasi budaya berarti masuknya unsur budaya asing ke dalam kehidupan sehari-hari. 2. Musik K-pop, film Hollywood, dan gerai makanan cepat saji adalah contoh yang akrab bagi remaja. 3. Musyawarah RT dan panen raya adalah budaya lokal Indonesia." },
    { q: "Contoh globalisasi di bidang IPTEK adalah....", options: ["penggunaan cangkul dalam bertani", "penggunaan internet dan media sosial", "permainan tradisional congklak", "surat menyurat lewat pos"], answer: 1, solution: "1. Kemajuan ilmu pengetahuan dan teknologi adalah motor utama globalisasi. 2. Internet dan media sosial menghubungkan manusia di seluruh dunia dalam hitungan detik. 3. Cangkul, congklak, dan surat pos adalah teknologi tradisional, bukan wujud globalisasi IPTEK." },
    { q: "Dampak positif globalisasi di bidang komunikasi dan informasi adalah....", options: ["berita palsu semakin sulit dilacak", "informasi menyebar cepat dan mudah diakses", "masyarakat malas membaca buku", "biaya komunikasi menjadi mahal"], answer: 1, solution: "1. Teknologi komunikasi modern memangkas jarak dan waktu. 2. Informasi dari belahan dunia mana pun bisa diakses lewat gawai dalam sekejap. 3. Berita palsu dan kemalasan membaca adalah dampak negatifnya, bukan positif." },
    { q: "Dampak negatif globalisasi di bidang ekonomi bagi Indonesia adalah....", options: ["terbukanya lapangan kerja baru", "meningkatnya devisa negara", "produk dalam negeri kalah bersaing dengan produk impor", "bertambahnya investor asing"], answer: 2, solution: "1. Pasar bebas membuat produk impor masuk dengan mudah dan murah. 2. Produk lokal yang kalah kualitas dan harga menjadi tersisih. 3. Lapangan kerja baru dan devisa justru termasuk dampak positif globalisasi ekonomi." },
    { q: "Dampak negatif globalisasi di bidang sosial bagi masyarakat Indonesia adalah....", options: ["meningkatnya toleransi antarumat beragama", "lunturnya gotong royong dan tumbuhnya individualisme", "berkembangnya organisasi kepemudaan", "meluasnya penggunaan bahasa Indonesia"], answer: 1, solution: "1. Budaya asing yang masuk tidak semuanya sesuai kepribadian bangsa. 2. Gaya hidup individualistis menggerus nilai gotong royong dan kebersamaan. 3. Toleransi dan organisasi kepemudaan justru contoh dampak positif di bidang sosial." },
    { q: "Sikap yang tepat dalam menghadapi masuknya budaya asing di era globalisasi adalah....", options: ["bersikap selektif, menyaring yang sesuai dengan kepribadian bangsa", "menerima semua budaya asing tanpa kecuali", "menolak seluruh budaya asing mentah-mentah", "melupakan budaya sendiri dan ikut budaya asing"], answer: 0, solution: "1. Globalisasi tidak bisa ditolak, tetapi bisa disikapi dengan bijak. 2. Sikap selektif berarti mengambil yang baik (misalnya etos kerja) dan menolak yang merusak (misalnya pergaulan bebas). 3. Menolak semua atau menerima semua sama-sama keliru karena tidak memilah manfaat dan mudaratnya." },
    { q: "Tantangan utama Indonesia di era globalisasi adalah....", options: ["menutup diri dari perdagangan dunia", "meningkatkan kualitas SDM agar mampu bersaing", "menghapus seluruh budaya daerah", "melarang penggunaan internet"], answer: 1, solution: "1. Persaingan global menuntut tenaga kerja yang terampil dan berdaya saing. 2. Karena itu Indonesia harus meningkatkan kualitas SDM lewat pendidikan dan pelatihan. 3. Menutup diri justru membuat Indonesia tertinggal dari bangsa lain." },
    { q: "Organisasi kerja sama internasional yang bertujuan menjaga perdamaian dunia dan didirikan pada 24 Oktober 1945 adalah....", options: ["ASEAN", "MEA", "PBB", "OKI"], answer: 2, solution: "1. Setelah Perang Dunia II, negara-negara sepakat membentuk badan perdamaian dunia. 2. Perserikatan Bangsa-Bangsa (PBB) resmi berdiri 24 Oktober 1945 dengan markas di New York. 3. ASEAN adalah kerja sama regional Asia Tenggara (1967), bukan organisasi perdamaian dunia." },
    { q: "Salah satu manfaat kerja sama internasional bagi Indonesia adalah....", options: ["mempercepat pembangunan nasional lewat bantuan modal dan teknologi", "kehilangan kedaulatan atas wilayah sendiri", "ketergantungan penuh pada negara lain", "terhapusnya budaya nasional"], answer: 0, solution: "1. Lewat kerja sama, Indonesia memperoleh modal, teknologi, dan pasar yang tidak dimiliki sendiri. 2. Hal ini mempercepat pembangunan di berbagai bidang. 3. Kerja sama yang sehat justru memperkuat posisi Indonesia, bukan menghilangkan kedaulatannya." }
  ]
};
